/* ------------------------------------------------------------------ */
/* Design tokens                                                       */
/* ------------------------------------------------------------------ */
/* Every token is a CSS variable rather than a literal, so the whole app
   re-themes by flipping one attribute on <html>. The inline styles all over
   this file keep working untouched — they just carry a var() through.
   The real values live in THEME_PALETTES below. */
const tokens = {
  ink: "var(--ink)",
  inkSoft: "var(--ink-soft)",
  muted: "var(--muted)",
  faint: "var(--faint)",
  border: "var(--border)",
  borderStrong: "var(--border-strong)",
  bg: "var(--bg)",
  surface: "var(--surface)",
  primary: "var(--primary)",
  primarySoft: "var(--primary-soft)",
  primaryHover: "var(--primary-hover)",
  onPrimary: "var(--on-primary)",       // text that sits on a filled primary button
  success: "var(--success)",
  successSoft: "var(--success-soft)",
  warning: "var(--warning)",
  warningSoft: "var(--warning-soft)",
  danger: "var(--danger)",
  dangerSoft: "var(--danger-soft)",
  info: "var(--info)",
  infoSoft: "var(--info-soft)",
  // Hairline borders for tinted callouts. These exist because a var() can't
  // have an alpha suffix appended the way a hex literal could.
  primaryRing: "var(--primary-ring)",
  successRing: "var(--success-ring)",
  warningRing: "var(--warning-ring)",
  dangerRing: "var(--danger-ring)",
  infoRing: "var(--info-ring)",
  scrim: "var(--scrim)",
  chip: "var(--chip)",
};

