// Five brand-derived avatar colours, each with a matching tint. Kept as a
// pair because a var() colour can't have an alpha suffix appended to it.
const AVATAR_COUNT = 5;
const avatarIndex = (seed) => (Math.abs(seed || 0) % AVATAR_COUNT) + 1;
function colorFor(seed) { return `var(--avatar-${avatarIndex(seed)})`; }
function colorSoftFor(seed) { return `var(--avatar-${avatarIndex(seed)}-soft)`; }

/* ================================================================== */
/* ATTENDANCE — configuration & policy                                 */
/* Single source of truth. No business rule is written inline anywhere  */
/* else in this file; screens read these objects. Swapping any value    */
/* here changes the whole module — that is the point (spec §86).        */
/* ================================================================== */

/* The clock follows the system — the device the app is opened on. There is
   no backend, so `new Date()` (the browser's local time) is "now". A real
   deployment would prefer a server timestamp, but the shape is identical. */
const _CLOCK = new Date();
const _pad = (n) => String(n).padStart(2, "0");
const TODAY_STR = _CLOCK.getFullYear() + "-" + _pad(_CLOCK.getMonth() + 1) + "-" + _pad(_CLOCK.getDate());
const SIM_NOW_MIN = _CLOCK.getHours() * 60 + _CLOCK.getMinutes();
const NOW_ISO = TODAY_STR + "T" + _pad(_CLOCK.getHours()) + ":" + _pad(_CLOCK.getMinutes()) + ":00";
// Days relative to today — used to anchor the seeded demo data (corrections,
// review periods, audit log) to whenever the app is actually opened, instead
// of a fixed 2026 date that drifts out of relevance.
function daysAgo(n) {
  const d = new Date(_CLOCK);
  d.setDate(d.getDate() - n);
  return d.getFullYear() + "-" + _pad(d.getMonth() + 1) + "-" + _pad(d.getDate());
}
// Most recent weekday that is on or before today — the day the demo
// scenarios land on, so there's always a rich board to look at even if the
// app is opened on a weekend.
function recentWeekday() {
  let d = new Date(_CLOCK);
  while (d.getDay() === 0 || d.getDay() === 6) d.setDate(d.getDate() - 1);
  return d.getFullYear() + "-" + _pad(d.getMonth() + 1) + "-" + _pad(d.getDate());
}
const SHOWCASE_DAY = recentWeekday();

// Calendar-day shift on a YYYY-MM-DD string (independent of the later
// addDays helper so the seed data below can use it).
function shift(dateStr, days) {
  const d = new Date(dateStr + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.getFullYear() + "-" + _pad(d.getMonth() + 1) + "-" + _pad(d.getDate());
}
// The Nth business day before/after `dateStr` (skips Sat/Sun) — used to place
// seeded corrections and history on days people actually worked.
function prevWorkday(dateStr, count = 1) {
  let d = new Date(dateStr + "T00:00:00");
  while (count > 0) { d.setDate(d.getDate() - 1); if (d.getDay() !== 0 && d.getDay() !== 6) count--; }
  return d.getFullYear() + "-" + _pad(d.getMonth() + 1) + "-" + _pad(d.getDate());
}
function nextWorkday(dateStr, count = 1) {
  let d = new Date(dateStr + "T00:00:00");
  while (count > 0) { d.setDate(d.getDate() + 1); if (d.getDay() !== 0 && d.getDay() !== 6) count--; }
  return d.getFullYear() + "-" + _pad(d.getMonth() + 1) + "-" + _pad(d.getDate());
}

// Every seeded date used by the demo, resolved once against the real clock.
// `d0` is the day the rich scenarios land on; `dN` are workdays before it.
const DEMO = {
  d0: SHOWCASE_DAY,
  d1: prevWorkday(SHOWCASE_DAY, 1),
  d2: prevWorkday(SHOWCASE_DAY, 2),
  d3: prevWorkday(SHOWCASE_DAY, 3),
  d5: prevWorkday(SHOWCASE_DAY, 5),
  d8: prevWorkday(SHOWCASE_DAY, 8),
  d12: prevWorkday(SHOWCASE_DAY, 12),
  n1: nextWorkday(SHOWCASE_DAY, 1),
  n2: nextWorkday(SHOWCASE_DAY, 2),
};

// Dates follow the chosen language: Bahasa Indonesia formatting when id,
// en-GB otherwise. One helper feeds every formatter below.
function dateLocale() { return LANG === "id" ? "id-ID" : "en-GB"; }
function todayLabel() { return fmtDayLabel(TODAY_STR); }
// Greeting follows the device clock, same source as SIM_NOW_MIN.
function greetingKey() {
  const h = _CLOCK.getHours();
  if (h < 11) return "Good morning, {name}";
  if (h < 15) return "Good day, {name}";
  if (h < 18) return "Good afternoon, {name}";
  return "Good evening, {name}";
}

