/* ------------------------------------------------------------------ */
/* Attendance vocabulary                                               */
/* ------------------------------------------------------------------ */

// Status — what happened. One value per employee per day.
const ATT_STATUS = {
  PRESENT: "Present", LATE: "Late", EARLY_LEAVE: "Early Leave",
  INCOMPLETE: "Incomplete", NOT_CLOCKED_IN: "Not Clocked In",
  ABSENT: "Absent", ON_LEAVE: "On Leave",
  FIELD_WORK: "Field Work", BUSINESS_TRIP: "Business Trip",
  WEEKEND: "Weekend", HOLIDAY: "Holiday",
};

// Risk — how much we trust the record. A SEPARATE axis from status
// (spec §9): "Late" is a fact about the day, "SUSPICIOUS" is a fact about
// the evidence. A record can be Present + HIGH_RISK, or Late + VALID.
const RISK = { VALID: "VALID", REVIEW: "REVIEW", SUSPICIOUS: "SUSPICIOUS", HIGH_RISK: "HIGH_RISK" };
const RISK_ORDER = { VALID: 0, REVIEW: 1, SUSPICIOUS: 2, HIGH_RISK: 3 };
const RISK_LABEL = { VALID: "Valid", REVIEW: "Review", SUSPICIOUS: "Suspicious", HIGH_RISK: "High risk" };
const RISK_TONE = { VALID: "muted", REVIEW: "info", SUSPICIOUS: "warning", HIGH_RISK: "danger" };
function riskWorst(a, b) { return RISK_ORDER[a] >= RISK_ORDER[b] ? a : b; }

// How the record reached us (spec §5, §6, §21).
const METHOD = { FINGERPRINT: "FINGERPRINT", MOBILE_GPS: "MOBILE_GPS", FIELD_WORK: "FIELD_WORK", HADIR: "HADIR" };
const METHOD_LABEL = {
  FINGERPRINT: "Fingerprint", MOBILE_GPS: "Mobile GPS",
  FIELD_WORK: "Field work", HADIR: "Hadir",
};
const METHOD_ICON = { FINGERPRINT: Fingerprint, MOBILE_GPS: Smartphone, FIELD_WORK: MapPin, HADIR: Download };

const LOC_KIND = {
  HEAD_OFFICE: "Head Office", WAREHOUSE: "Warehouse",
  REGISTERED: "Registered Customer Location", UNREGISTERED: "Unregistered Field Location",
};

const CORRECTION_STATE = { NONE: "none", PENDING: "Pending", APPROVED: "Approved", REJECTED: "Rejected" };

function attendanceStatusTone(s) {
  // Deliberately NOT the shared statusTone() — that one serves employment
  // status and would silently mis-tone the attendance vocabulary.
  return {
    "Present": "success", "Late": "warning", "Early Leave": "warning",
    "Incomplete": "warning", "Not Clocked In": "danger", "Absent": "danger",
    "On Leave": "info", "Field Work": "info", "Business Trip": "info",
    "Weekend": "muted", "Holiday": "muted",
  }[s] || "muted";
}

function hashSeed(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (h << 5) - h + str.charCodeAt(i); h |= 0; }
  return Math.abs(h);
}
function pseudo(seed) {
  const x = Math.sin(seed) * 10000;
  return x - Math.floor(x);
}
function toMinutes(t) { const [h, m] = t.split(":").map(Number); return h * 60 + m; }
function fromMinutes(mins) {
  mins = ((mins % 1440) + 1440) % 1440;
  return String(Math.floor(mins / 60)).padStart(2, "0") + ":" + String(mins % 60).padStart(2, "0");
}
function formatDuration(mins) {
  if (mins === null || mins === undefined) return "—";
  const h = Math.floor(mins / 60), m = mins % 60;
  return `${h}h ${String(m).padStart(2, "0")}m`;
}
function fmtDateLabel(dateStr) {
  return new Date(dateStr + "T00:00:00").toLocaleDateString(dateLocale(), { weekday: "long", day: "2-digit", month: "long", year: "numeric" });
}
function fmtDateShort(dateStr) {
  return new Date(dateStr + "T00:00:00").toLocaleDateString(dateLocale(), { day: "2-digit", month: "short", year: "numeric" });
}

/* ------------------------------------------------------------------ */
/* Date helpers                                                        */
/* ------------------------------------------------------------------ */
function isoDate(d) {
  return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function addDays(dateStr, n) {
  const d = new Date(dateStr + "T00:00:00"); d.setDate(d.getDate() + n); return isoDate(d);
}
function addMonths(dateStr, n) {
  const d = new Date(dateStr + "T00:00:00"); d.setMonth(d.getMonth() + n); return isoDate(d);
}
function dowOf(dateStr) { return new Date(dateStr + "T00:00:00").getDay(); }
function holidayFor(dateStr) { return HOLIDAYS.find((h) => h.date === dateStr) || null; }
function fmtDayLabel(dateStr) {
  return new Date(dateStr + "T00:00:00")
    .toLocaleDateString(dateLocale(), { weekday: "long", day: "numeric", month: "long", year: "numeric" });
}
function fmtDateTime(iso) {
  return new Date(iso).toLocaleString(dateLocale(),
    { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });
}
function parseHHMM(s) {
  if (!s) return null;
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(s).trim());
  if (!m) return null;
  const h = +m[1], mm = +m[2];
  if (h > 23 || mm > 59) return null;
  return h * 60 + mm;
}
// Compact delta: 11 -> "11m", 95 -> "1h 35m". formatDuration() is too wide
// for a dense table column.
function fmtDelta(mins) {
  if (!mins) return "—";
  const h = Math.floor(mins / 60), m = mins % 60;
  return (h ? h + "h " : "") + m + "m";
}

/* ------------------------------------------------------------------ */
/* Weekly review period — Saturday → Friday (spec §30)                 */
/* ------------------------------------------------------------------ */
function weeklyPeriod(dateStr) {
  const back = (dowOf(dateStr) - ATTENDANCE_POLICY.weekStartDow + 7) % 7;
  const startDate = addDays(dateStr, -back);
  const endDate = addDays(startDate, 6);
  // Built by hand: en-GB inserts a comma once the year is included, which
  // would give the two ends of the range different shapes.
  const f = (s, withYear) => {
    const d = new Date(s + "T00:00:00");
    const wd = d.toLocaleDateString(dateLocale(), { weekday: "short" });
    const dm = d.toLocaleDateString(dateLocale(), { day: "numeric", month: "short" });
    return `${wd} ${dm}${withYear ? " " + d.getFullYear() : ""}`;
  };
  return {
    id: "WK-" + startDate, startDate, endDate,
    label: f(startDate, false) + " – " + f(endDate, true),
    days: Array.from({ length: 7 }, (_, i) => addDays(startDate, i)),
  };
}
function shiftPeriodStart(startDate, weeks) { return addDays(startDate, 7 * weeks); }
// Land on the newest COMPLETE week — the current one is still running.
function defaultPeriodStart(todayStr) {
  const c = weeklyPeriod(todayStr);
  return todayStr < c.endDate ? shiftPeriodStart(c.startDate, -1) : c.startDate;
}

/* ------------------------------------------------------------------ */
/* Schedule resolution & derivation                                    */
/* ------------------------------------------------------------------ */
// Employees carry no site field (that data is owned by the Employees
// module and is not ours to change), so the site comes from department
// with a per-person override list.
const SITE_OVERRIDE = {};
function siteKeyFor(emp) {
  if (!emp) return "Head Office";
  if (SITE_OVERRIDE[emp.id]) return SITE_OVERRIDE[emp.id];
  return emp.dept === "Operations" ? "Warehouse" : "Head Office";
}
function scheduleForEmployee(emp) { return WORK_SCHEDULES[siteKeyFor(emp)] || WORK_SCHEDULES["Head Office"]; }

// Friday shifts the break earlier at both sites; everything else is constant.
function breakWindow(sched, dateStr) {
  const fri = dowOf(dateStr) === 5;
  return {
    start: toMinutes(fri ? sched.fridayBreakStart : sched.breakStart),
    end: toMinutes(fri ? sched.fridayBreakEnd : sched.breakEnd),
  };
}
function breakMinutes(sched, dateStr) {
  const b = breakWindow(sched, dateStr); return b.end - b.start;
}
function computeWorkedMinutes(sched, dateStr, inMin, outMin) {
  if (inMin == null || outMin == null) return null;
  const b = breakWindow(sched, dateStr);
  const overlap = Math.max(0, Math.min(outMin, b.end) - Math.max(inMin, b.start));
  return Math.max(0, outMin - inMin - overlap);
}
function computeArrival(sched, inMin) {
  if (inMin == null) return { late: false, lateMin: 0 };
  const grace = toMinutes(sched.graceUntil);
  if (inMin <= grace) return { late: false, lateMin: 0 };
  return { late: true, lateMin: inMin - grace };
}
function computeDeparture(sched, outMin) {
  if (outMin == null) return { earlyLeaveMin: 0, otMin: 0 };
  const end = toMinutes(sched.end);
  // Tapping out four minutes past the hour is not overtime. Anything under
  // the configured threshold is normal end-of-day noise.
  const overrun = Math.max(0, outMin - end);
  return {
    earlyLeaveMin: Math.max(0, end - outMin),
    otMin: overrun >= ATTENDANCE_POLICY.overtimeThresholdMin ? overrun : 0,
  };
}
function mealEligibleFor(inMin) {
  if (inMin == null) return false;
  const cut = toMinutes(ATTENDANCE_POLICY.mealCutoff);
  return ATTENDANCE_POLICY.mealCutoffInclusive ? inMin <= cut : inMin < cut;
}
function allowanceFor(record) {
  const key =
    ["Weekend", "Holiday"].includes(record.status) ? "WEEKEND" :
    record.status === ATT_STATUS.ON_LEAVE ? "LEAVE" :
    record.status === ATT_STATUS.ABSENT ? "ABSENT" :
    record.status === ATT_STATUS.BUSINESS_TRIP ? "BUSINESS_TRIP" :
    record.status === ATT_STATUS.FIELD_WORK ? "FIELD_WORK" : "ON_SITE";
  const rule = ALLOWANCE_RULES[key];
  const meal = rule.meal === "cutoff" ? !!record.mealEligible : rule.meal;
  return { key, label: rule.label, meal, transport: rule.transport, credit: rule.credit };
}

