/* ------------------------------------------------------------------ */
/* Risk scoring (spec §9, §10, §35, §36)                               */
/* Additive signals, never a single-factor rejection. The engine only   */
/* classifies; every decision below is made by a person.                */
/* ------------------------------------------------------------------ */
const RISK_SIGNAL_WEIGHT = {
  mockGps: 45, impossibleTravel: 38, livenessFailed: 24, faceLow: 24,
  deviceUntrusted: 20, clockSkew: 20, accuracyVeryLow: 18, unregisteredLocation: 12,
  accuracyLow: 12, hadirImport: 8, syncDelayed: 10,
};
// Risk reasons are stored as { key, vars } so the drawer and the weekly
// review can render them in either language. reasonText() flattens one.
function reasonText(r) { return typeof r === "string" ? t(r) : t(r.key, r.vars); }

function scoreRisk(signals, opts = {}) {
  const reasons = [];
  let score = 0;
  const add = (w, key, vars) => { score += w; reasons.push({ key, vars: vars || {} }); };

  if (signals.mockGps === true) add(RISK_SIGNAL_WEIGHT.mockGps, "The device reported a mock (simulated) location.");
  if (signals.impossibleTravel === true) add(RISK_SIGNAL_WEIGHT.impossibleTravel, "The distance from the previous check-in is hard to cover in the time between them.");
  if (signals.liveness === false) add(RISK_SIGNAL_WEIGHT.livenessFailed, "The liveness check did not complete.");
  if (signals.faceMatch != null && signals.faceMatch < 0.8) add(RISK_SIGNAL_WEIGHT.faceLow, "Face match came back below the usual level.");
  if (signals.deviceTrusted === false) add(RISK_SIGNAL_WEIGHT.deviceUntrusted, "Check-in came from a device that is not registered to this employee.");
  if (signals.timestampOk === false) add(RISK_SIGNAL_WEIGHT.clockSkew, "The device clock differs from the server clock.");
  if (signals.gpsAccuracyM != null && signals.gpsAccuracyM > 150) add(RISK_SIGNAL_WEIGHT.accuracyVeryLow, "Location accuracy was very low (±{n} m).", { n: signals.gpsAccuracyM });
  else if (signals.gpsAccuracyM != null && signals.gpsAccuracyM > 50) add(RISK_SIGNAL_WEIGHT.accuracyLow, "Location accuracy was lower than preferred (±{n} m).", { n: signals.gpsAccuracyM });
  if (signals.unregisteredLocation === true && !opts.trip) add(RISK_SIGNAL_WEIGHT.unregisteredLocation, "This location is not in the registered list. That is allowed — it just needs a look.");
  if (signals.hadirImport === true) add(RISK_SIGNAL_WEIGHT.hadirImport, "Imported from Hadir — location and photo checks are not available for this day.");
  if (signals.syncDelayed === true) add(RISK_SIGNAL_WEIGHT.syncDelayed, "The device synced later than usual.");

  // Out-of-town work is expected to be far from a site; don't punish it twice.
  if (opts.trip) score = Math.max(0, score - 12);

  let level = score >= 60 ? RISK.HIGH_RISK : score >= 35 ? RISK.SUSPICIOUS : score >= 12 ? RISK.REVIEW : RISK.VALID;
  // Spec §9/§36: one imperfect signal is never enough to call something
  // high risk on its own. Two or more, weighed together, can be.
  const hits = reasons.length;
  if (hits <= 1 && level === RISK.HIGH_RISK) level = RISK.SUSPICIOUS;
  return { level, score: Math.min(100, score), reasons, signals, autoReject: false };
}
const emptyRisk = () => ({ level: RISK.VALID, score: 0, reasons: [], signals: {}, autoReject: false });

/* ------------------------------------------------------------------ */
/* Demo scenarios (spec §35, §36)                                      */
/* Pinned so every status, every risk level and every capture method is */
/* visible on the landing day instead of depending on a lucky draw.     */
/* ------------------------------------------------------------------ */
const ATTENDANCE_SCENARIOS = [
  // The signed-in HR admin has not clocked in yet today, so the "My
  // Attendance" screen opens on the simulate-check-in flow.
  { employeeId: "EMP-0001", date: DEMO.d0, force: { status: "Not Clocked In" } },
  // 1 — an ordinary Head Office day.
  { employeeId: "EMP-0142", date: DEMO.d0,
    force: { status: "Present", method: METHOD.FINGERPRINT, in: "08:25", out: "17:39" } },
  // 2 — late at Head Office. 09:12 is 12 min past the 09:00 tolerance, not 42 past 08:30.
  { employeeId: "EMP-0098", date: DEMO.d0,
    force: { status: "Late", method: METHOD.FINGERPRINT, in: "09:12", out: "17:34" } },
  // 3 — Warehouse, inside its own earlier tolerance.
  { employeeId: "EMP-0056", date: DEMO.d0,
    force: { status: "Present", method: METHOD.FINGERPRINT, in: "08:21", out: "17:06" } },
  // 4 — field sales: office fingerprint first, then a mobile check-in at a registered customer.
  { employeeId: "EMP-0402", date: DEMO.d0,
    force: { status: "Field Work", method: METHOD.FIELD_WORK, fieldWorkRef: "FWR-011" } },
  // 5 — unregistered field location. Allowed, captured, flagged for a look. NOT rejected.
  { employeeId: "EMP-0059", date: DEMO.d0,
    force: { status: "Field Work", method: METHOD.FIELD_WORK, fieldWorkRef: "FWR-012",
             signals: { gpsAccuracyM: 180, unregisteredLocation: true, faceMatch: 0.94, liveness: true, deviceTrusted: true, timestampOk: true } } },
  // 6 — two strong signals together: mock GPS and an impossible jump.
  { employeeId: "EMP-0421", date: DEMO.d0,
    force: { status: "Present", method: METHOD.MOBILE_GPS, in: "08:05", out: "17:35",
             signals: { mockGps: true, impossibleTravel: true, gpsAccuracyM: 14, faceMatch: 0.96, liveness: true, deviceTrusted: false, timestampOk: true } } },
  // 7 — clocked in, never clocked out — on the previous workday, so the day has ended.
  { employeeId: "EMP-0033", date: DEMO.d1,
    force: { status: "Incomplete", method: METHOD.MOBILE_GPS, in: "08:36", out: null } },
  // 8 — the day COR-0003 refers to.
  { employeeId: "EMP-0421", date: DEMO.d2,
    force: { status: "Late", method: METHOD.FINGERPRINT, in: "09:20", out: "17:00" } },

  // Coverage for the remaining statuses and sources.
  { employeeId: "EMP-0288", date: DEMO.d0,
    force: { status: "Business Trip", method: METHOD.MOBILE_GPS, in: "08:40", out: "17:05", fieldWorkRef: "FWR-013" } },
  { employeeId: "EMP-0119", date: DEMO.d0,
    force: { status: "Early Leave", method: METHOD.FINGERPRINT, in: "08:29", out: "15:10" } },
  { employeeId: "EMP-0087", date: DEMO.d0, force: { status: "Absent" } },
  { employeeId: "EMP-0231", date: DEMO.d0, force: { status: "On Leave" } },
  { employeeId: "EMP-0078", date: DEMO.d0,
    force: { status: "Late", method: METHOD.FINGERPRINT, in: "08:52", out: "17:03" } },
  // A Hadir-imported day: times only, no location or photo to inspect.
  { employeeId: "EMP-0311", date: DEMO.d0,
    force: { status: "Present", method: METHOD.HADIR, in: "08:12", out: "17:20" } },
  { employeeId: "EMP-0204", date: DEMO.d0,
    force: { status: "Present", method: METHOD.MOBILE_GPS, in: "08:41", out: "17:33",
             signals: { gpsAccuracyM: 22, faceMatch: 0.97, liveness: true, deviceTrusted: true, timestampOk: true } } },
  // Days referenced by the seeded corrections, pinned so the "current"
  // column of the comparison view matches what the employee described.
  { employeeId: "EMP-0231", date: DEMO.d3,
    force: { status: "Incomplete", method: METHOD.FINGERPRINT, in: null, out: "17:05" } },
  { employeeId: "EMP-0059", date: DEMO.d1,
    force: { status: "Incomplete", method: METHOD.FINGERPRINT, in: "08:10", out: null } },
  { employeeId: "EMP-0142", date: DEMO.d8,
    force: { status: "Early Leave", method: METHOD.FINGERPRINT, in: "08:02", out: "15:30" } },
  { employeeId: "EMP-0176", date: DEMO.d12,
    force: { status: "Late", method: METHOD.FINGERPRINT, in: "08:50", out: "17:00" } },

  // The previous review period — the week HR finalises. Field work, an
  // unregistered location and a high-risk record all need to be present
  // there or the weekly review can't demonstrate its own queue.
  { employeeId: "EMP-0402", date: DEMO.d5,
    force: { status: "Field Work", method: METHOD.FIELD_WORK, fieldWorkRef: "FWR-008" } },
  { employeeId: "EMP-0059", date: DEMO.d3,
    force: { status: "Field Work", method: METHOD.FIELD_WORK, fieldWorkRef: "FWR-009",
             signals: { gpsAccuracyM: 210, unregisteredLocation: true, faceMatch: 0.93, liveness: true, deviceTrusted: true, timestampOk: true } } },
  { employeeId: "EMP-0033", date: DEMO.d5,
    force: { status: "Present", method: METHOD.MOBILE_GPS, in: "08:14", out: "17:36",
             signals: { mockGps: true, deviceTrusted: false, gpsAccuracyM: 16, faceMatch: 0.95, liveness: true, timestampOk: true } } },
];
function scenarioFor(empId, dateStr) {
  const s = ATTENDANCE_SCENARIOS.find((x) => x.employeeId === empId && x.date === dateStr);
  return s ? s.force : null;
}

// Only these people run field visits; everyone else is site-bound.
const FIELD_CAPABLE = ["EMP-0059", "EMP-0193", "EMP-0402"];
function isFieldCapable(emp) { return !!emp && FIELD_CAPABLE.includes(emp.id); }
// Two employees were on the old Hadir app before the rollout.
const HADIR_EMPLOYEES = ["EMP-0311", "EMP-0087"];

/* ------------------------------------------------------------------ */
/* Record builders                                                     */
/* ------------------------------------------------------------------ */
function buildLocation(method, sched, dateStr, opts = {}) {
  if (method === METHOD.HADIR) return null; // Hadir sends no location at all
  if (method === METHOD.FINGERPRINT) {
    return { kind: sched.key === "Warehouse" ? LOC_KIND.WAREHOUSE : LOC_KIND.HEAD_OFFICE,
             label: sched.key, lat: sched.geo.lat, lng: sched.geo.lng, accuracyM: null, registered: true };
  }
  if (opts.trip) {
    return { kind: LOC_KIND.UNREGISTERED, label: (opts.city || "Out of town"), tripLabel: true,
             lat: -7.2575, lng: 112.7521, accuracyM: opts.accuracyM ?? 25, registered: false, trip: true };
  }
  const loc = opts.locationRef ? locationById(opts.locationRef) : null;
  if (loc) {
    return { kind: LOC_KIND.REGISTERED, label: loc.name, isCustomer: true, lat: loc.lat, lng: loc.lng,
             accuracyM: opts.accuracyM ?? 18, registered: true, locationRef: loc.id, address: loc.address };
  }
  if (method === METHOD.FIELD_WORK) {
    return { kind: LOC_KIND.UNREGISTERED, label: "Unregistered location", lat: -6.2610, lng: 106.8106,
             accuracyM: opts.accuracyM ?? 120, registered: false };
  }
  // Mobile GPS from an office — near the site geofence. `viaMobile` keeps the
  // label a translatable key instead of a baked-in "Head Office (mobile)".
  return { kind: sched.key === "Warehouse" ? LOC_KIND.WAREHOUSE : LOC_KIND.HEAD_OFFICE,
           label: sched.key, viaMobile: true, lat: sched.geo.lat, lng: sched.geo.lng,
           accuracyM: opts.accuracyM ?? 20, registered: true };
}

// Renders a location's display name in the current language. Customer names
// and trip cities are data and pass through untranslated.
function locLabel(loc) {
  if (!loc) return "—";
  if (loc.tripLabel) return t("{city} — business trip", { city: loc.label });
  const base = loc.isCustomer ? loc.label : t(loc.label);
  return loc.viaMobile ? t("{site} (mobile)", { site: base }) : base;
}

function buildEvidence(method, sched, emp, dateStr, opts = {}) {
  const base = { simulated: true, integrationPending: true, method };
  if (method === METHOD.FINGERPRINT) {
    const dev = deviceById(sched.deviceId);
    const reg = fingerprintRegFor(emp);
    return { ...base, source: "device", deviceId: sched.deviceId, deviceLabel: deviceLabelFor(sched.deviceId),
             devicePlacement: dev ? dev.placement : "—", fingerId: reg.fingerId, enrolQuality: reg.quality,
             syncedAt: dev ? dev.lastSync : null };
  }
  if (method === METHOD.HADIR) {
    return { ...base, source: "hadir", deviceLabel: "Hadir (imported)",
             importedAt: HADIR_SOURCE.lastImport, syncStatus: HADIR_SOURCE.status, note: HADIR_SOURCE.note };
  }
  const dev = mobileDeviceFor(emp.id);
  return { ...base, source: "mobile-app", deviceId: dev.id, deviceLabel: dev.label,
           deviceOs: dev.os, appVersion: dev.appVersion, deviceTrusted: dev.trusted,
           capturedAt: opts.capturedAt || null,
           photoRef: null, // always null — a placeholder is drawn, never a fake photo
           // Raw values, formatted for display (and language) at render time.
           faceMatchPct: opts.faceMatch != null ? Math.round(opts.faceMatch * 100) : null,
           livenessOk: opts.liveness !== false,
           purpose: opts.purpose || null, customer: opts.customer || null };
}

function mkRecord(emp, dateStr, sched, patch) {
  return {
    id: "ATT-" + emp.id + "-" + dateStr,
    employeeId: emp.id, date: dateStr, scheduleKey: sched.key,
    weekday: dowOf(dateStr),
    expectedIn: sched.start, expectedOut: sched.end, toleranceUntil: sched.graceUntil,
    status: null, method: null, workLocation: null,
    clockIn: null, clockOut: null,
    workedMin: null, lateMin: 0, earlyLeaveMin: 0, otMin: 0,
    breakMin: breakMinutes(sched, dateStr),
    mealEligible: null,
    risk: emptyRisk(), evidence: { simulated: true, integrationPending: true },
    fieldWorkRef: null, sessions: null,
    correction: { state: CORRECTION_STATE.NONE, id: null },
    corrected: false,
    source: "generated",
    ...patch,
  };
}

/* The generator. Deterministic on (employee, date): the same day always
   renders the same way, so screenshots and demos are stable. */
function generateDayRecord(emp, dateStr, ctx = {}) {
  const today = ctx.today || TODAY_STR;
  const sched = scheduleForEmployee(emp);
  const dow = dowOf(dateStr);
  const isToday = dateStr === today;

  if (dow === 0 || dow === 6) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.WEEKEND });
  const hol = holidayFor(dateStr);
  if (hol) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.HOLIDAY, holidayName: hol.name });
  if (dateStr > today) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.NOT_CLOCKED_IN, future: true });
  if (emp.joinDate && dateStr < emp.joinDate) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.WEEKEND, preHire: true });

  const forced = ctx.scenario || scenarioFor(emp.id, dateStr);
  if (forced) return buildForcedRecord(emp, dateStr, sched, forced, today);

  if (!DEMO_DATA) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.NOT_CLOCKED_IN });

  const seed = hashSeed(emp.id + "|" + dateStr);
  let k = 0;
  const rnd = () => pseudo(seed + (k++));
  const rInt = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

  // Employment status colours the draw: someone marked On Leave in the
  // Employees module should mostly be on leave here too.
  const onLeaveBias = emp.status === "On Leave" ? 0.42 : 0.035;
  const p = rnd();
  if (p < onLeaveBias) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.ON_LEAVE });
  if (p < onLeaveBias + 0.03) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.ABSENT });
  if (isToday && p < onLeaveBias + 0.05) return mkRecord(emp, dateStr, sched, { status: ATT_STATUS.NOT_CLOCKED_IN });

  if (isFieldCapable(emp) && rnd() < 0.35) return buildFieldRecord(emp, dateStr, sched, null, rnd, rInt, today);

  const method = pickMethod(emp, dateStr, rnd);
  const graceMin = toMinutes(sched.graceUntil), startMin = toMinutes(sched.start), endMin = toMinutes(sched.end);

  const rLate = rnd();
  const inMin = rLate < 0.14 ? graceMin + rInt(1, 55)
    : rLate < 0.175 ? graceMin + rInt(60, 170)   // occasionally past the meal cut-off
    : rInt(startMin - 12, graceMin);

  let outMin;
  const rOut = rnd();
  if (isToday && inMin < SIM_NOW_MIN && rOut < 0.72) outMin = null;      // still at work
  else if (!isToday && rOut < 0.06) outMin = null;                       // forgot to tap out
  else {
    const rEnd = rnd();
    outMin = rEnd < 0.08 ? endMin - rInt(15, 95)
      : rEnd < 0.28 ? endMin + rInt(20, 130)
      : endMin + rInt(0, 14);
  }
  if (isToday && outMin != null && outMin > SIM_NOW_MIN) outMin = null;

  const signals = drawSignals(method, rnd, mobileDeviceFor(emp.id));
  return finishRecord(emp, dateStr, sched, { method, inMin, outMin, signals, isToday });
}

function pickMethod(emp, dateStr, rnd) {
  if (HADIR_EMPLOYEES.includes(emp.id) && dateStr < shift(TODAY_STR, -20) && rnd() < 0.55) return METHOD.HADIR;
  const r = rnd();
  if (r < 0.86) return METHOD.FINGERPRINT;
  if (r < 0.98) return METHOD.MOBILE_GPS;
  return METHOD.HADIR;
}

function drawSignals(method, rnd, dev) {
  if (method === METHOD.FINGERPRINT) return { syncDelayed: rnd() < 0.05 };
  if (method === METHOD.HADIR) return { hadirImport: true };
  const g = rnd();
  return {
    gpsAccuracyM: Math.round(8 + Math.pow(rnd(), 3) * 220),
    mockGps: g < 0.012,
    impossibleTravel: g >= 0.012 && g < 0.028,
    deviceTrusted: dev ? dev.trusted : true,
    faceMatch: Math.max(0.6, Math.min(0.999, 0.995 - Math.pow(rnd(), 4) * 0.4)),
    liveness: rnd() >= 0.02,
    timestampOk: rnd() >= 0.015,
  };
}

// Turns raw in/out minutes into the full record: status, derived minutes,
// location, evidence and risk. One place, so every screen agrees.
function finishRecord(emp, dateStr, sched, o) {
  const { method, inMin, outMin, signals = {}, isToday, locationRef, trip, city, purpose, customer, fieldWorkRef, forceStatus } = o;
  const arrival = computeArrival(sched, inMin);
  const departure = computeDeparture(sched, outMin);
  const worked = computeWorkedMinutes(sched, dateStr, inMin, outMin);

  // Someone who is clocked in at 14:20 on a working day is at work, not
  // "Incomplete". A missing clock-out is only an exception once the shift
  // has actually ended — otherwise half the office lands in the review
  // queue every afternoon and the queue stops meaning anything.
  const stillWorking = isToday && SIM_NOW_MIN < toMinutes(sched.end);

  let status = forceStatus;
  if (!status) {
    if (inMin == null) status = isToday ? ATT_STATUS.NOT_CLOCKED_IN : ATT_STATUS.ABSENT;
    else if (outMin == null && !stillWorking) status = ATT_STATUS.INCOMPLETE;
    else if (arrival.late) status = ATT_STATUS.LATE;
    else if (outMin != null && departure.earlyLeaveMin >= ATTENDANCE_POLICY.earlyLeaveStatusMin) status = ATT_STATUS.EARLY_LEAVE;
    else status = ATT_STATUS.PRESENT;
  }

  const accuracyM = signals.gpsAccuracyM;
  const workLocation = buildLocation(method, sched, dateStr, { locationRef, trip, city, accuracyM });
  const sig = { ...signals };
  if (workLocation && workLocation.registered === false && !trip) sig.unregisteredLocation = true;

  const evidence = buildEvidence(method, sched, emp, dateStr, {
    capturedAt: inMin != null ? fromMinutes(inMin) : null,
    faceMatch: signals.faceMatch, liveness: signals.liveness, purpose, customer,
  });

  // Off-site work isn't measured against the office clock: someone on a
  // business trip has not "left early" because they weren't due at a desk.
  const offSite = [ATT_STATUS.FIELD_WORK, ATT_STATUS.BUSINESS_TRIP].includes(status);

  return mkRecord(emp, dateStr, sched, {
    status, method,
    workLocation,
    clockIn: inMin != null ? fromMinutes(inMin) : null,
    clockOut: outMin != null ? fromMinutes(outMin) : null,
    workedMin: worked,
    lateMin: offSite ? 0 : arrival.lateMin,
    earlyLeaveMin: offSite ? 0 : departure.earlyLeaveMin,
    otMin: offSite ? 0 : departure.otMin,
    mealEligible: inMin != null ? mealEligibleFor(inMin) : null,
    risk: scoreRisk(sig, { trip }),
    evidence,
    fieldWorkRef: fieldWorkRef || null,
    source: method === METHOD.HADIR ? "import" : "device",
  });
}

/* A field day is two or three sessions rolled into one row: the office
   fingerprint on the way out, the customer visit, sometimes a return tap.
   The employee does not have to come back to the office (spec §15). */
function buildFieldRecord(emp, dateStr, sched, fwrIn, rnd, rInt, today) {
  const fwr = fwrIn || fieldWorkRequestFor(emp.id, dateStr) || synthFieldRequest(emp, dateStr, rnd);
  const isToday = dateStr === today;

  if (fwr.kind === "trip") {
    const inMin = toMinutes(sched.start) + rInt(-10, 40);
    let outMin = toMinutes(sched.end) + rInt(-40, 50);
    if (isToday && outMin > SIM_NOW_MIN) outMin = null;
    const signals = { gpsAccuracyM: 24, faceMatch: 0.96, liveness: true, deviceTrusted: true, timestampOk: true };
    return finishRecord(emp, dateStr, sched, {
      method: METHOD.MOBILE_GPS, inMin, outMin, signals, isToday, trip: true, city: fwr.city,
      purpose: fwr.purpose, fieldWorkRef: fwr.id, forceStatus: ATT_STATUS.BUSINESS_TRIP,
    });
  }

  const sessions = [];
  const needsOffice = fwr.requiresOfficeCheckIn;
  if (needsOffice) {
    const oIn = toMinutes(sched.start) + rInt(-8, 18);
    const oOut = toMinutes(fwr.plannedStart) - rInt(15, 40);
    sessions.push({
      seq: 1, kind: "office-checkin", label: "Office check-in", method: METHOD.FINGERPRINT,
      clockIn: fromMinutes(oIn), clockOut: fromMinutes(oOut),
      location: buildLocation(METHOD.FINGERPRINT, sched, dateStr, {}),
      deviceLabel: deviceLabelFor(sched.deviceId),
      risk: emptyRisk(),
    });
  }
  const fIn = toMinutes(fwr.plannedStart) + rInt(-10, 25);
  let fOut = toMinutes(fwr.plannedEnd) + rInt(-25, 40);
  if (isToday && fOut > SIM_NOW_MIN) fOut = null;
  const fSignals = {
    gpsAccuracyM: fwr.locationRef ? rInt(10, 40) : rInt(60, 190),
    mockGps: false, impossibleTravel: false, deviceTrusted: mobileDeviceFor(emp.id).trusted,
    faceMatch: 0.93 + rnd() * 0.06, liveness: true, timestampOk: true,
  };
  const fLoc = buildLocation(METHOD.FIELD_WORK, sched, dateStr, { locationRef: fwr.locationRef, accuracyM: fSignals.gpsAccuracyM });
  if (!fLoc.registered) fSignals.unregisteredLocation = true;
  const fRisk = scoreRisk(fSignals, {});
  sessions.push({
    seq: sessions.length + 1, kind: "field-visit", label: "Field visit", method: METHOD.FIELD_WORK,
    clockIn: fromMinutes(fIn), clockOut: fOut != null ? fromMinutes(fOut) : null,
    location: fLoc, deviceLabel: mobileDeviceFor(emp.id).label,
    note: fwr.purpose, customer: fwr.customer, risk: fRisk,
  });

  const firstIn = toMinutes(sessions[0].clockIn);
  const lastOut = sessions[sessions.length - 1].clockOut;
  const lastOutMin = lastOut != null ? toMinutes(lastOut) : null;
  const workedMin = sessions.reduce((s, seg) =>
    s + (seg.clockOut ? computeWorkedMinutes(sched, dateStr, toMinutes(seg.clockIn), toMinutes(seg.clockOut)) : 0), 0);
  const arrival = computeArrival(sched, firstIn);
  const rolledRisk = sessions.reduce((w, s) => riskWorst(w, s.risk.level), RISK.VALID);
  const rolledReasons = sessions.reduce((acc, s) => acc.concat(s.risk.reasons), []);

  const rec = mkRecord(emp, dateStr, sched, {
    status: ATT_STATUS.FIELD_WORK, method: METHOD.FIELD_WORK,
    workLocation: fLoc,
    clockIn: sessions[0].clockIn, clockOut: lastOut,
    workedMin: workedMin || null,
    lateMin: arrival.lateMin,
    earlyLeaveMin: 0,
    otMin: lastOutMin != null ? computeDeparture(sched, lastOutMin).otMin : 0,
    mealEligible: mealEligibleFor(firstIn),
    risk: { level: rolledRisk, score: fRisk.score, reasons: rolledReasons, signals: fSignals, autoReject: false },
    evidence: buildEvidence(METHOD.FIELD_WORK, sched, emp, dateStr, {
      capturedAt: sessions[sessions.length - 1].clockIn, faceMatch: fSignals.faceMatch,
      liveness: true, purpose: fwr.purpose, customer: fwr.customer,
    }),
    fieldWorkRef: fwr.id, sessions, source: "device",
  });
  if (fwr.status === "Pending") {
    rec.risk = { ...rec.risk, level: riskWorst(rec.risk.level, RISK.REVIEW),
      reasons: rec.risk.reasons.concat([{ key: "The field-work request for this day has not been approved yet.", vars: {} }]) };
  }
  return rec;
}

function synthFieldRequest(emp, dateStr, rnd) {
  const useRegistered = rnd() < 0.7;
  const loc = REGISTERED_LOCATIONS[Math.floor(rnd() * 3)];
  const startMin = 540 + Math.floor(rnd() * 90);
  return {
    id: "FWR-" + (100 + (hashSeed(emp.id + dateStr) % 800)),
    employeeId: emp.id, date: dateStr, kind: "visit", endDate: null,
    purpose: ["Customer visit", "Delivery follow-up", "Account check-in", "Site survey"][Math.floor(rnd() * 4)],
    customer: useRegistered ? loc.name : null,
    locationRef: useRegistered ? loc.id : null, city: null,
    plannedStart: fromMinutes(startMin), plannedEnd: fromMinutes(startMin + 210 + Math.floor(rnd() * 120)),
    status: "Approved", approver: emp.manager || "—", decidedAt: null,
    requiresOfficeCheckIn: rnd() < 0.6, synthesised: true,
  };
}

function buildForcedRecord(emp, dateStr, sched, force, today) {
  const isToday = dateStr === today;
  if ([ATT_STATUS.ABSENT, ATT_STATUS.ON_LEAVE, ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY, ATT_STATUS.NOT_CLOCKED_IN].includes(force.status)) {
    return mkRecord(emp, dateStr, sched, { status: force.status });
  }
  const seed = hashSeed(emp.id + "|" + dateStr + "|forced");
  let k = 0;
  const rnd = () => pseudo(seed + (k++));
  const rInt = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

  if (force.status === ATT_STATUS.FIELD_WORK) {
    const fwr = force.fieldWorkRef ? FIELD_WORK_REQUESTS.find((f) => f.id === force.fieldWorkRef) : null;
    const rec = buildFieldRecord(emp, dateStr, sched, fwr, rnd, rInt, today);
    if (force.signals) {
      const merged = { ...rec.risk.signals, ...force.signals };
      const scored = scoreRisk(merged, {});
      rec.risk = scored;
      if (rec.workLocation) rec.workLocation.accuracyM = merged.gpsAccuracyM ?? rec.workLocation.accuracyM;
      if (rec.sessions) {
        const visit = rec.sessions.find((s) => s.kind === "field-visit");
        if (visit) { visit.risk = scored; if (visit.location) visit.location.accuracyM = merged.gpsAccuracyM ?? visit.location.accuracyM; }
      }
    }
    return rec;
  }

  if (force.status === ATT_STATUS.BUSINESS_TRIP) {
    const fwr = force.fieldWorkRef ? FIELD_WORK_REQUESTS.find((f) => f.id === force.fieldWorkRef) : null;
    const inMin = parseHHMM(force.in);
    let outMin = force.out === null ? null : parseHHMM(force.out);
    if (isToday && outMin != null && outMin > SIM_NOW_MIN) outMin = null;
    const signals = { gpsAccuracyM: 26, faceMatch: 0.96, liveness: true, deviceTrusted: true, timestampOk: true, ...(force.signals || {}) };
    return finishRecord(emp, dateStr, sched, {
      method: force.method || METHOD.MOBILE_GPS, inMin, outMin, signals, isToday,
      trip: true, city: fwr ? fwr.city : "Out of town", purpose: fwr ? fwr.purpose : null,
      fieldWorkRef: fwr ? fwr.id : null, forceStatus: ATT_STATUS.BUSINESS_TRIP,
    });
  }

  const method = force.method || METHOD.FINGERPRINT;
  const inMin = force.in === null || force.in === undefined ? null : parseHHMM(force.in);
  let outMin = force.out === null || force.out === undefined ? null : parseHHMM(force.out);
  let status = force.status;
  // A pinned scenario is a story about a whole day. If the app is opened
  // before that day is over, the check-out hasn't happened yet — drop it and
  // let the record read as in-progress rather than showing a future time.
  if (isToday && outMin != null && outMin > SIM_NOW_MIN) {
    outMin = null;
    if (status === ATT_STATUS.EARLY_LEAVE) status = inMin != null && computeArrival(sched, inMin).late ? ATT_STATUS.LATE : ATT_STATUS.PRESENT;
    if (status === ATT_STATUS.INCOMPLETE) status = inMin != null && computeArrival(sched, inMin).late ? ATT_STATUS.LATE : ATT_STATUS.PRESENT;
  }
  const signals = { ...drawSignals(method, rnd, mobileDeviceFor(emp.id)), ...(force.signals || {}) };
  return finishRecord(emp, dateStr, sched, {
    method, inMin, outMin, signals, isToday, forceStatus: status,
  });
}

/* ------------------------------------------------------------------ */
/* Lookups + aggregation                                               */
/* ------------------------------------------------------------------ */
function employeeById(id) {
  const e = employees.find((x) => x.id === id);
  if (e) return e;
  if (id === SELF.id) return SELF;
  return { id, name: id, dept: "—", position: "", manager: "—", colorSeed: 0, joinDate: "2020-01-01", status: "Active" };
}
function dayRecordById(empId, dateStr, ctx) {
  return generateDayRecord(employeeById(empId), dateStr, ctx);
}
// The roster everything counts against: active people only. Someone marked
// Inactive in the Employees module should not sit in today's "absent" pile.
function activeRoster() { return employees.filter((e) => e.status !== "Inactive"); }

function getRecords(empId, from, to, ctx) {
  const out = [];
  let d = from;
  while (d <= to) { out.push(dayRecordById(empId, d, ctx)); d = addDays(d, 1); }
  return out.reverse(); // newest first
}
function monthRangeOf(monthKey, today) {
  const first = monthKey + "-01";
  const d = new Date(first + "T00:00:00");
  const last = isoDate(new Date(d.getFullYear(), d.getMonth() + 1, 0));
  return { from: first, to: last > (today || TODAY_STR) ? (today || TODAY_STR) : last };
}
function getMonthRecords(empId, year, month, ctx) {
  const key = `${year}-${String(month).padStart(2, "0")}`;
  const r = monthRangeOf(key, ctx && ctx.today);
  return getRecords(empId, r.from, r.to, ctx);
}

function monthSummary(records) {
  const has = (...s) => (r) => s.includes(r.status);
  const n = (f) => records.filter(f).length;
  const sum = (f) => records.reduce((a, r) => a + (f(r) || 0), 0);
  return {
    workdays: n((r) => !["Weekend", "Holiday"].includes(r.status)),
    present: n(has("Present", "Incomplete", "Early Leave", "Field Work", "Business Trip")),
    late: n(has("Late")),
    absent: n(has("Absent")),
    leave: n(has("On Leave")),
    earlyLeave: n(has("Early Leave")),
    fieldWork: n(has("Field Work", "Business Trip")),
    incomplete: n(has("Incomplete")),
    overtimeMin: sum((r) => r.otMin),
    lateMin: sum((r) => r.lateMin),
    correctionPending: n((r) => r.correction.state === CORRECTION_STATE.PENDING),
    needsReview: n((r) => RISK_ORDER[r.risk.level] >= 1),
  };
}

function todayBoard(roster, dateStr, getRecord) {
  const day = dateStr || TODAY_STR;
  const read = getRecord || ((id, d) => dayRecordById(id, d));
  const rows = roster.map((e) => ({ e, r: read(e.id, day) }));
  const n = (f) => rows.filter(f).length;
  return {
    rows,
    counts: {
      present: n(({ r }) => ["Present", "Early Leave", "Incomplete"].includes(r.status)),
      late: n(({ r }) => r.status === "Late"),
      absent: n(({ r }) => r.status === "Absent"),
      onLeave: n(({ r }) => r.status === "On Leave"),
      notClockedIn: n(({ r }) => r.status === "Not Clocked In"),
      fieldWork: n(({ r }) => ["Field Work", "Business Trip"].includes(r.status)),
      needsReview: n(({ r }) => RISK_ORDER[r.risk.level] >= 1),
    },
  };
}
// Kept for the dashboard's five-day strip.
function todaySummary(roster) { return todayBoard(roster, TODAY_STR).counts; }

function last5Workdays(dateStr) {
  const out = [];
  let d = dateStr;
  while (out.length < 5) {
    const dow = dowOf(d);
    if (dow !== 0 && dow !== 6 && !holidayFor(d)) out.unshift(d);
    d = addDays(d, -1);
  }
  return out;
}

const SELF = {
  id: "EMP-0001", name: DEMO_DATA ? "Sri Wahyuni" : "Administrator", dept: "Human Resources", position: "HR Admin",
  manager: "—", colorSeed: 99, role: "HR", joinDate: "2019-01-07", status: "Active",
};

/* ------------------------------------------------------------------ */
/* Role scope (spec §39)                                               */
/* Written as functions taking (role, viewer, target) rather than as    */
/* `if (menu)` checks, so the same predicates can move to the API when  */
/* there is one. Hiding a tab is a convenience, not the control.        */
/* ------------------------------------------------------------------ */
const ATTENDANCE_ROLES = ["Employee", "Supervisor", "Manager", "HR", "Accounting", "Director"];

// Demo affordance: each role previews the module as a plausible person.
const VIEWER_FOR_ROLE = {
  Employee: "EMP-0142", Supervisor: "EMP-0176", Manager: "EMP-0078",
  HR: "EMP-0001", Accounting: "EMP-0288", Director: "EMP-0267",
};
function resolveViewer(role) {
  const id = VIEWER_FOR_ROLE[role] || SELF.id;
  return id === SELF.id ? SELF : employeeById(id);
}

const ATTENDANCE_SEGMENTS = [
  { key: "overview", label: "Overview", roles: ["Supervisor", "Manager", "HR", "Accounting", "Director"] },
  // Everyone employed has their own attendance record and can query a fix to it.
  { key: "my", label: "My Attendance", roles: ["Employee", "Supervisor", "Manager", "HR", "Accounting", "Director"] },
  { key: "team", label: "Team", roles: ["Supervisor", "Manager", "HR"] },
  { key: "corrections", label: "Corrections", roles: ["Employee", "Supervisor", "Manager", "HR", "Accounting", "Director"] },
  { key: "review", label: "Weekly Review", roles: ["HR"] },
  { key: "sources", label: "Devices & Sources", roles: ["HR", "Director"] },
];
function segmentsFor(role) { return ATTENDANCE_SEGMENTS.filter((s) => s.roles.includes(role)); }

// May this viewer see this person's attendance at all?
function canScope(role, viewer, target) {
  if (!target) return false;
  switch (role) {
    case "Employee": return target.id === viewer.id;
    case "Supervisor": return target.id === viewer.id || target.manager === viewer.name;
    case "Manager": return target.id === viewer.id || target.manager === viewer.name || target.dept === viewer.dept;
    case "HR": return true;
    case "Accounting": return true;  // payroll-relevant rows, but no evidence drawer
    case "Director": return true;    // aggregate only — see canOpenDetail
    default: return target.id === viewer.id;
  }
}
function scopedRoster(role, viewer) { return activeRoster().filter((e) => canScope(role, viewer, e)); }
// Accounting and Director get numbers, not someone's selfie and GPS trace.
function canOpenDetail(role) { return ["Employee", "Supervisor", "Manager", "HR"].includes(role); }
function canSeeEvidence(role) { return ["Supervisor", "Manager", "HR"].includes(role); }
function canSeeRisk(role) { return role !== "Employee" && role !== "Accounting"; }
function canSeeAllowance(role) { return role === "HR" || role === "Accounting"; }
function canApproveCorrections(role) { return role === "HR"; }
function canRunWeeklyReview(role) { return role === "HR"; }

/* ================================================================== */
/* ACCOUNT PROVISIONING & FIRST SIGN-IN (spec §18, §19, §72)           */
/* HR creates the person; the person creates their own credentials.    */
/* HR never sets, sees or holds anyone's password — they only issue a  */
/* one-time activation code that stops working once it is used.        */
/* ================================================================== */

const ACCOUNT_STATUS = {
  PENDING: "Pending",          // employee record exists, no invitation sent yet
  INVITED: "Invited",          // code issued — waiting for the person to set their own details
  ACTIVE: "Active",            // they chose a username and password
  SUSPENDED: "Suspended",
  DEACTIVATED: "Deactivated",
};
const ACCOUNT_STATUS_TONE = {
  "Pending": "muted", "Invited": "warning", "Active": "success",
  "Suspended": "warning", "Deactivated": "muted",
};

const ACCOUNT_POLICY = {
  usernameMin: 4,
  usernameMax: 24,
  usernameAllowed: /^[a-z0-9._-]+$/,
  passwordMin: 10,
  passwordNeedsLetterAndNumber: true,
  activationValidDays: 14,
  // Deliberately NOT configurable: nobody but the account holder ever sets
  // the password. There is no "HR sets a starting password" path.
  employeeChoosesOwnCredentials: true,
};

/* The one instruction every role gets — employee, supervisor, manager,
   accounting, director and HR read exactly the same five steps. Defined
   once so the wording cannot drift between the activation screen, the
   admin console and whatever HR pastes into an email. */
const ACCOUNT_SETUP_TITLE = "Setting up your sign-in";
const ACCOUNT_SETUP_INTRO =
  "Everyone at Serenity — from new starters to directors — creates their own username and password the first time they sign in. HR issues a one-time activation code and nothing else. No one else ever knows your password.";
const ACCOUNT_SETUP_STEPS = [
  "Go to Serenity HRIS and choose “First time signing in”.",
  "Enter your company email and the one-time activation code HR gave you.",
  "Choose your own username. It is yours — HR does not pick it for you.",
  "Set a password only you know: at least 10 characters, with a letter and a number.",
  "Sign in with the username and password you just created. The activation code stops working straight away.",
];
const ACCOUNT_SETUP_FOOTNOTE =
  "If the code has expired or you did not receive one, ask HR to re-issue it. HR can reset an account, but cannot see or choose your password.";

function accountSetupPlainText() {
  return [
    t(ACCOUNT_SETUP_TITLE), "", t(ACCOUNT_SETUP_INTRO), "",
    ...ACCOUNT_SETUP_STEPS.map((step, i) => `${i + 1}. ${t(step)}`),
    "", t(ACCOUNT_SETUP_FOOTNOTE),
  ].join("\n");
}

// A ready-to-send invitation. There is no mail server here — this is the text
// HR hands the new person (by email, chat, on paper). `openInviteEmail` opens
// the admin's own mail client with it pre-filled.
function inviteEmailBody(account, kind) {
  const emp = employeeById(account.employeeId);
  const code = activationCodeFor(account.employeeId);
  const first = (emp.name || "").split(" ")[0] || emp.name || "";
  return [
    t("Hi {name},", { name: first }),
    "",
    kind === "reminder"
      ? t("A reminder to set up your Serenity HRIS sign-in — it is still waiting for you.")
      : t("An account has been created for you in Serenity HRIS."),
    "",
    t("Company email: {email}", { email: account.email }),
    t("One-time activation code: {code}", { code }),
    "",
    ...ACCOUNT_SETUP_STEPS.map((s, i) => `${i + 1}. ${t(s)}`),
    "",
    t(ACCOUNT_SETUP_FOOTNOTE),
  ].join("\n");
}
function openInviteEmail(account, kind) {
  const subject = kind === "reminder"
    ? t("Reminder: set up your Serenity HRIS sign-in")
    : t("Your Serenity HRIS account");
  const href = `mailto:${encodeURIComponent(account.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(inviteEmailBody(account, kind))}`;
  try {
    const a = document.createElement("a");
    a.href = href; a.style.display = "none";
    document.body.appendChild(a); a.click(); a.remove();
  } catch (e) { /* no mail client configured */ }
}

// Deterministic per-employee so the demo can display a code that stays put.
function activationCodeFor(empId) {
  const alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // no I/O/0/1 — they get misread aloud
  let h = hashSeed(empId + "|activation");
  let out = "";
  for (let i = 0; i < 6; i++) { out += alphabet[h % alphabet.length]; h = Math.floor(h / alphabet.length) + 7 * (i + 1); }
  return out.slice(0, 3) + "-" + out.slice(3);
}

// Which HRIS role this person signs in as. Derived from their real position
// so the demo doesn't need a separate role table.
function roleForEmployee(emp) {
  if (!emp) return "Employee";
  if (emp.id === SELF.id) return "HR";
  const p = (emp.position || "").toLowerCase();
  if (emp.dept === "Human Resources" && (p.includes("manager") || p.includes("admin"))) return "HR";
  if (p.includes("accountant") || p.includes("finance manager")) return "Accounting";
  if (p.includes("manager") || p.includes("head")) return "Manager";
  if (p.includes("supervisor")) return "Supervisor";
  return "Employee";
}

