/* Dashboard feeds — derived from the same engine as every other screen,
   so the numbers on the dashboard and inside Attendance cannot disagree. */
function buildAttendanceTrend(getRecord) {
  const roster = activeRoster();
  const ID_DOW = { 1: "Sen", 2: "Sel", 3: "Rab", 4: "Kam", 5: "Jum" };
  return last5Workdays(TODAY_STR).map((d) => {
    const b = todayBoard(roster, d, getRecord);
    return { day: ID_DOW[dowOf(d)] || fmtDateShort(d), present: b.counts.present, late: b.counts.late };
  });
}
function buildNeedsAttention(corrections, getRecord) {
  const b = todayBoard(activeRoster(), TODAY_STR, getRecord);
  const pendingCorr = (corrections || SEED_CORRECTIONS).filter((c) => c.state === "Pending").length;
  const rows = [
    b.counts.notClockedIn > 0 && { icon: Clock, tone: "danger", seg: "overview", filter: "missing_in",
      text: t(b.counts.notClockedIn === 1 ? "{n} employee has no check-in today" : "{n} employees have no check-in today", { n: b.counts.notClockedIn }), action: t("Review") },
    b.counts.needsReview > 0 && { icon: AlertTriangle, tone: "warning", seg: "overview", filter: "flagged",
      text: t(b.counts.needsReview === 1 ? "{n} attendance record flagged for review" : "{n} attendance records flagged for review", { n: b.counts.needsReview }), action: t("Review") },
    // Someone is waiting on HR for these, so they outrank calendar notices.
    pendingCorr > 0 && { icon: FileText, tone: "warning", seg: "corrections", filter: null,
      text: t(pendingCorr === 1 ? "{n} attendance correction pending" : "{n} attendance corrections pending", { n: pendingCorr }), action: t("Review") },
    DEMO_DATA && { icon: CalendarDays, tone: "info", seg: null, filter: null, text: t("5 leave requests awaiting approval"), action: t("Review") },
    DEMO_DATA && { icon: FileWarning, tone: "info", seg: null, filter: null, text: t("2 contracts expire this month"), action: t("View") },
  ].filter(Boolean);
  const rank = { danger: 0, warning: 1, info: 2 };
  return rows.sort((a, b2) => rank[a.tone] - rank[b2.tone]);
}

