function Avatar({ name, color, soft, size = 32 }) {
  const initials = name.split(" ").map((n) => n[0]).slice(0, 2).join("");
  return (
    <div
      style={{
        width: size, height: size, borderRadius: 999, background: soft || tokens.primarySoft,
        color, display: "flex", alignItems: "center", justifyContent: "center",
        fontSize: size * 0.38, fontWeight: 600, flexShrink: 0,
      }}
    >
      {initials}
    </div>
  );
}

function Button({ children, variant = "primary", size = "md", icon: Icon, onClick, style, disabled, type = "button", title, ariaLabel }) {
  const base = {
    display: "inline-flex", alignItems: "center", gap: 6, justifyContent: "center",
    fontFamily: fontStack, fontWeight: 500, borderRadius: 8, cursor: disabled ? "not-allowed" : "pointer",
    // Longhand only — the variants below override borderColor, and mixing it
    // with the `border` shorthand makes React warn on re-render.
    borderWidth: 1, borderStyle: "solid", borderColor: "transparent",
    transition: "background 120ms, border-color 120ms",
    fontSize: size === "sm" ? 13 : 13.5, padding: size === "sm" ? "6px 10px" : "8px 14px",
    opacity: disabled ? 0.5 : 1,
  };
  const variants = {
    primary: { background: tokens.primary, color: tokens.onPrimary },
    secondary: { background: tokens.surface, color: tokens.ink, borderColor: tokens.borderStrong },
    ghost: { background: "transparent", color: tokens.inkSoft },
    danger: { background: tokens.surface, color: tokens.danger, borderColor: tokens.dangerSoft },
  };
  return (
    <button
      type={type} disabled={disabled} onClick={onClick}
      title={title} aria-label={ariaLabel}
      style={{ ...base, ...variants[variant], ...style }}
    >
      {Icon && <Icon size={15} />}
      {children}
    </button>
  );
}

function Badge({ tone = "muted", children }) {
  const map = {
    success: [tokens.successSoft, tokens.success],
    warning: [tokens.warningSoft, tokens.warning],
    danger: [tokens.dangerSoft, tokens.danger],
    info: [tokens.infoSoft, tokens.info],
    muted: [tokens.chip, tokens.inkSoft],
  };
  const [bg, fg] = map[tone];
  return (
    <span style={{ background: bg, color: fg, fontSize: 12, fontWeight: 600, padding: "2px 8px", borderRadius: 6, whiteSpace: "nowrap" }}>
      {children}
    </span>
  );
}

function statusTone(status) {
  return { Active: "success", "On Leave": "info", Probation: "warning", Inactive: "muted", Present: "success", Late: "warning", Absent: "danger", Weekend: "muted", Approved: "success", Pending: "warning", Rejected: "danger" }[status] || "muted";
}

