/* Reads the same engine as the Attendance module — the profile tab is a
   view onto that data, not a second dataset (spec §34). */
function AttendanceTab({ employeeId, onOpenAttendance, store, viewerRole = "Employee", viewerId }) {
  const [month, setMonth] = useState(TODAY_STR.slice(0, 7));
  const [openRecord, setOpenRecord] = useState(null);
  // Same drill-in rule as the module: HR / Supervisor / Manager can open any
  // record; a plain Employee only their own; Accounting / Director never.
  const canDrill = canOpenDetail(viewerRole) && (viewerRole !== "Employee" || viewerId === employeeId);
  const getRecord = store ? store.getRecord : (id, d) => dayRecordById(id, d);
  const corrections = store ? store.corrections : SEED_CORRECTIONS;

  const monthOptions = useMemo(() => {
    const out = [];
    let k = TODAY_STR.slice(0, 7);
    for (let i = 0; i < 6; i++) {
      out.push({ key: k, label: new Date(k + "-01T00:00:00").toLocaleDateString(dateLocale(), { month: "long", year: "numeric" }) });
      k = addMonths(k + "-01", -1).slice(0, 7);
    }
    return out;
  }, [LANG]);

  const records = useMemo(() => {
    const r = monthRangeOf(month, TODAY_STR);
    const out = [];
    let d = r.from;
    while (d <= r.to) { out.push(decorateRecord(getRecord(employeeId, d))); d = addDays(d, 1); }
    return out.reverse();
  }, [employeeId, month, getRecord]);

  const workRecords = records.filter((r) => r._workday);
  const summary = monthSummary(records);
  const pending = corrections.filter((c) => c.employeeId === employeeId && c.state === "Pending").length;

  return (
    <Card
      title={t("Attendance history")}
      action={
        <Select value={month} onChange={(e) => setMonth(e.target.value)} style={{ width: 160 }}>
          {monthOptions.map((m) => <option key={m.key} value={m.key}>{m.label}</option>)}
        </Select>
      }
    >
      <div style={{ display: "flex", gap: 24, padding: "0 16px 14px", flexWrap: "wrap" }}>
        {[
          [t("Present"), summary.present], [t("Late"), summary.late], [t("Early leave"), summary.earlyLeave],
          [t("Field work"), summary.fieldWork], [t("Overtime"), formatDuration(summary.overtimeMin)],
          [t("Corrections"), pending ? t("{n} pending", { n: pending }) : t("None")],
        ].map(([l, v]) => (
          <div key={l}>
            <div style={{ fontSize: 16, fontWeight: 600, color: tokens.ink, fontVariantNumeric: "tabular-nums" }}>{v}</div>
            <div style={{ fontSize: 12, color: tokens.muted }}>{l}</div>
          </div>
        ))}
      </div>

      <div style={{ borderTop: `1px solid ${tokens.border}` }}>
        <AttendanceTable
          rows={workRecords.slice().sort(ATT_SORTERS.date)}
          columns={["date", "in", "out", "hours", "method", "location", "late", "ot", "status", ...(canSeeRisk(viewerRole) ? ["risk"] : [])]}
          minWidth={900}
          onRowClick={canDrill ? setOpenRecord : null}
          emptyState={<EmptyState icon={Clock} title={t("No attendance records")} subtitle={t("Nothing recorded for this month.")} />}
        />
      </div>

      <div style={{ padding: "10px 16px", borderTop: `1px solid ${tokens.border}` }}>
        <Button variant="ghost" icon={ArrowRight} onClick={() => onOpenAttendance && onOpenAttendance()}>{t("Open in Attendance")}</Button>
      </div>

      {openRecord && canDrill && (
        <AttendanceDetailDrawer
          key={openRecord.id}
          record={openRecord}
          employee={employeeById(employeeId)}
          role={viewerRole}
          viewerId={viewerId}
          onClose={() => setOpenRecord(null)}
          onOpenCorrection={null}
        />
      )}
    </Card>
  );
}

