/* Employees — Add flow                                                 */
/* ------------------------------------------------------------------ */
const addSteps = ["Personal", "Employment", "Compensation", "Documents", "Review"];

function StepIndicator({ step }) {
  return (
    <div style={{ display: "flex", alignItems: "center", marginBottom: 26 }}>
      {addSteps.map((s, i) => {
        const n = i + 1;
        const state = n < step ? "done" : n === step ? "active" : "todo";
        return (
          <React.Fragment key={s}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{
                width: 24, height: 24, borderRadius: 999, display: "flex", alignItems: "center", justifyContent: "center",
                fontSize: 12, fontWeight: 600, flexShrink: 0,
                background: state === "todo" ? tokens.bg : tokens.primary,
                color: state === "todo" ? tokens.faint : tokens.onPrimary,
                border: state === "todo" ? `1px solid ${tokens.borderStrong}` : "none",
              }}>
                {state === "done" ? <Check size={13} /> : n}
              </div>
              <span style={{ fontSize: 13, fontWeight: state === "active" ? 600 : 500, color: state === "todo" ? tokens.faint : tokens.ink, whiteSpace: "nowrap" }} className="hris-step-label">{t(s)}</span>
            </div>
            {i < addSteps.length - 1 && <div style={{ flex: 1, height: 1, background: tokens.border, margin: "0 12px" }} />}
          </React.Fragment>
        );
      })}
    </div>
  );
}

const emptyForm = {
  fullName: "", dob: "", gender: "", phone: "", email: "", address: "",
  emName: "", emRelation: "", emPhone: "",
  employeeId: "", dept: "", position: "", manager: "", type: "Full-time", status: "Probation", joinDate: "", contractEnd: "",
  salary: "", allowances: "", payFrequency: "Monthly", effectiveDate: "",
  documents: [],
};

// "EMP-0512" style, one above the current highest.
function nextEmployeeId() {
  // Start above the bootstrap admin (EMP-0001) so the first real hire is
  // EMP-0002 and never collides with SELF.
  const base = Number(String(SELF.id).replace(/\D/g, "")) || 0;
  const n = employees.reduce((mx, e) => Math.max(mx, Number(String(e.id).replace(/\D/g, "")) || 0), base) + 1;
  return "EMP-" + String(n).padStart(4, "0");
}
function parseRupiah(s) { return Number(String(s || "").replace(/[^\d]/g, "")) || 0; }

function AddEmployeeFlow({ onCancel, onCreated, onCreate }) {
  const [step, setStep] = useState(1);
  const [form, setForm] = useState(emptyForm);
  const [errors, setErrors] = useState({});
  const [success, setSuccess] = useState(false);
  const [created, setCreated] = useState(null);
  const fileInputRef = useRef(null);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  // Build the real employee record + a Pending account, hand both to App.
  const commit = () => {
    const id = form.employeeId.trim() || nextEmployeeId();
    const salary = parseRupiah(form.salary);
    const emp = {
      id, name: form.fullName.trim(), dept: form.dept, position: form.position,
      manager: form.manager || "—", type: form.type, status: form.status,
      joinDate: form.joinDate,
      email: form.email.trim() || `${form.fullName.trim().toLowerCase().split(/\s+/).join(".")}@nusantara.co.id`,
      phone: form.phone || "—", address: form.address || "—",
      dob: form.dob || "—", gender: form.gender || "—",
      salary, allowance: parseRupiah(form.allowances) || Math.round(salary * 0.12 / 50000) * 50000,
      contractEnd: (form.type === "Contract" || form.type === "Intern") ? (form.contractEnd || null) : null,
      emergency: { name: form.emName || "—", relation: form.emRelation || "—", phone: form.emPhone || "—" },
      colorSeed: employees.length,
    };
    onCreate && onCreate(emp);
    setCreated(emp);
    setSuccess(true);
  };

  const validateStep = () => {
    const errs = {};
    if (step === 1) {
      if (!form.fullName.trim()) errs.fullName = t("Please enter the employee's full name.");
      if (form.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(form.email)) errs.email = t("Please enter a valid email address.");
    }
    if (step === 2) {
      if (!form.dept) errs.dept = t("Please select a department.");
      if (!form.position) errs.position = t("Please select a position.");
      if (!form.type) errs.type = t("Please select an employment type.");
      if (!form.joinDate) errs.joinDate = t("Please select a join date.");
    }
    setErrors(errs);
    return Object.keys(errs).length === 0;
  };

  const next = () => { if (validateStep()) setStep((s) => Math.min(5, s + 1)); };
  const back = () => setStep((s) => Math.max(1, s - 1));

  const addMockFile = (name) => {
    setForm((f) => ({ ...f, documents: [...f.documents, { name, status: "uploaded", size: (Math.round(Math.random() * 900) + 100) + " KB" }] }));
  };
  const removeFile = (name) => setForm((f) => ({ ...f, documents: f.documents.filter((d) => d.name !== name) }));

  if (success) {
    return (
      <div style={{ padding: 24, maxWidth: 560, margin: "60px auto", textAlign: "center" }}>
        <div style={{ width: 52, height: 52, borderRadius: 999, background: tokens.successSoft, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto 16px" }}>
          <CheckCircle2 size={26} color={tokens.success} />
        </div>
        <h1 style={{ fontSize: 19, fontWeight: 600, color: tokens.ink, marginBottom: 6 }}>{t("Employee created")}</h1>
        <p style={{ fontSize: 13.5, color: tokens.muted, marginBottom: 20 }}>
          {t("{name} has been added to your organization.", { name: form.fullName || "The new employee" })}
        </p>

        {/* The one step HR forgets: the person still has no way in. */}
        <div style={{ textAlign: "left", marginBottom: 22 }}>
          <div style={{ display: "flex", gap: 10, background: tokens.warningSoft, border: `1px solid ${tokens.warningRing}`, borderRadius: 10, padding: "12px 14px", marginBottom: 12 }}>
            <AlertTriangle size={17} color={tokens.warning} style={{ flexShrink: 0, marginTop: 1 }} />
            <div>
              <div style={{ fontSize: 13, fontWeight: 600, color: tokens.ink }}>{t("They can't sign in yet")}</div>
              <p style={{ fontSize: 12.5, color: tokens.inkSoft, margin: "3px 0 0", lineHeight: 1.55 }}>
                {t("Send the invitation from Administration → Awaiting first sign-in, then pass on the steps below. {name} will choose their own username and password — you don’t set either one.", { name: form.fullName ? form.fullName.split(" ")[0] : t("They") })}
              </p>
            </div>
          </div>
          <AccountSetupInstructions compact />
        </div>

        <div style={{ display: "flex", gap: 8, justifyContent: "center", flexWrap: "wrap" }}>
          <Button onClick={onCreated}>{t("View employees")}</Button>
          <Button variant="secondary" onClick={() => { setForm(emptyForm); setStep(1); setSuccess(false); setCreated(null); }}>{t("Add another employee")}</Button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: 24, maxWidth: 760, margin: "0 auto" }}>
      <div
        onClick={onCancel}
        style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 13, color: tokens.muted, cursor: "pointer", marginBottom: 16 }}
      >
        <ArrowLeft size={14} /> {t("Cancel")}
      </div>
      <h1 style={{ fontSize: 19, fontWeight: 600, color: tokens.ink, marginBottom: 20 }}>{t("Add employee")}</h1>

      <StepIndicator step={step} />

      <Card style={{ padding: 24 }}>
        {step === 1 && (
          <div>
            <h2 style={{ fontSize: 14.5, fontWeight: 600, marginTop: 0, marginBottom: 16 }}>{t("Personal information")}</h2>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }} className="hris-form-grid">
              <Field label={t("Full name")} required error={errors.fullName}><TextInput value={form.fullName} onChange={set("fullName")} placeholder={t("e.g. Andi Pratama")} error={errors.fullName} /></Field>
              <Field label={t("Date of birth")}><TextInput type="date" value={form.dob} onChange={set("dob")} /></Field>
              <Field label={t("Gender")}>
                <Select value={form.gender} onChange={set("gender")}><option value="">{t("Select gender")}</option><option value="Male">{t("Male")}</option><option value="Female">{t("Female")}</option></Select>
              </Field>
              <Field label={t("Phone")}><TextInput value={form.phone} onChange={set("phone")} placeholder="0812-0000-0000" /></Field>
              <Field label={t("Email")} error={errors.email}><TextInput value={form.email} onChange={set("email")} placeholder="name@company.co.id" error={errors.email} /></Field>
              <Field label={t("Address")}><TextInput value={form.address} onChange={set("address")} placeholder={t("Street, city")} /></Field>
            </div>
            <div style={{ marginTop: 6, marginBottom: 4, fontSize: 12.5, fontWeight: 600, color: tokens.inkSoft }}>{t("Emergency contact")}</div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "0 16px" }} className="hris-form-grid-3">
              <Field label={t("Name")}><TextInput value={form.emName} onChange={set("emName")} /></Field>
              <Field label={t("Relationship")}><TextInput value={form.emRelation} onChange={set("emRelation")} placeholder={t("Spouse, parent...")} /></Field>
              <Field label={t("Phone")}><TextInput value={form.emPhone} onChange={set("emPhone")} /></Field>
            </div>
          </div>
        )}

        {step === 2 && (
          <div>
            <h2 style={{ fontSize: 14.5, fontWeight: 600, marginTop: 0, marginBottom: 16 }}>{t("Employment")}</h2>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }} className="hris-form-grid">
              <Field label={t("Employee ID")} hint={t("Leave blank to auto-generate")}><TextInput value={form.employeeId} onChange={set("employeeId")} placeholder="EMP-0000" /></Field>
              <Field label={t("Department")} required error={errors.dept}>
                <Select value={form.dept} error={errors.dept} onChange={(e) => setForm((f) => ({ ...f, dept: e.target.value, position: "" }))}>
                  <option value="">{t("Select department")}</option>
                  {departments.map((d) => <option key={d} value={d}>{d}</option>)}
                </Select>
              </Field>
              <Field label={t("Position")} required error={errors.position}>
                <Select value={form.position} error={errors.position} onChange={set("position")} disabled={!form.dept}>
                  <option value="">{form.dept ? t("Select position") : t("Select department first")}</option>
                  {(positionsByDept[form.dept] || []).map((p) => <option key={p} value={p}>{p}</option>)}
                </Select>
              </Field>
              <Field label={t("Manager")}>
                <Select value={form.manager} onChange={set("manager")}>
                  <option value="">{t("Select manager")}</option>
                  {employees.filter((e) => !form.dept || e.dept === form.dept).map((e) => <option key={e.id} value={e.name}>{e.name}</option>)}
                </Select>
              </Field>
              <Field label={t("Employment type")} required error={errors.type}>
                <Select value={form.type} error={errors.type} onChange={set("type")}>
                  {employmentTypes.map((t) => <option key={t} value={t}>{t}</option>)}
                </Select>
              </Field>
              <Field label={t("Employment status")}>
                <Select value={form.status} onChange={set("status")}>
                  {employmentStatuses.map((s) => <option key={s} value={s}>{s}</option>)}
                </Select>
              </Field>
              <Field label={t("Join date")} required error={errors.joinDate}><TextInput type="date" value={form.joinDate} onChange={set("joinDate")} error={errors.joinDate} /></Field>
              {(form.type === "Contract" || form.type === "Intern") && (
                <Field label={t("Contract end date")}><TextInput type="date" value={form.contractEnd} onChange={set("contractEnd")} /></Field>
              )}
            </div>
          </div>
        )}

        {step === 3 && (
          <div>
            <h2 style={{ fontSize: 14.5, fontWeight: 600, marginTop: 0, marginBottom: 16 }}>{t("Compensation")}</h2>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 16px" }} className="hris-form-grid">
              <Field label={t("Basic salary")} hint={t("Enter amount in IDR")}><TextInput value={form.salary} onChange={set("salary")} placeholder="8.000.000" /></Field>
              <Field label={t("Allowances")}><TextInput value={form.allowances} onChange={set("allowances")} placeholder="1.000.000" /></Field>
              <Field label={t("Payroll frequency")}>
                <Select value={form.payFrequency} onChange={set("payFrequency")}><option value="Monthly">{t("Monthly")}</option><option value="Bi-weekly">{t("Bi-weekly")}</option></Select>
              </Field>
              <Field label={t("Effective date")}><TextInput type="date" value={form.effectiveDate} onChange={set("effectiveDate")} /></Field>
            </div>
          </div>
        )}

        {step === 4 && (
          <div>
            <h2 style={{ fontSize: 14.5, fontWeight: 600, marginTop: 0, marginBottom: 6 }}>{t("Documents")}</h2>
            <p style={{ fontSize: 12.5, color: tokens.muted, marginTop: 0, marginBottom: 16 }}>{t("Prototype only — files are simulated and not persisted.")}</p>
            <div
              onClick={() => fileInputRef.current?.click()}
              style={{ border: `1.5px dashed ${tokens.borderStrong}`, borderRadius: 10, padding: "28px 16px", textAlign: "center", cursor: "pointer", background: tokens.bg, marginBottom: 16 }}
            >
              <Upload size={20} color={tokens.faint} style={{ marginBottom: 8 }} />
              <div style={{ fontSize: 13, color: tokens.inkSoft }}>{t("Drag & drop files, or ")}<span style={{ color: tokens.primary, fontWeight: 600 }}>{t("browse")}</span></div>
              <div style={{ fontSize: 11.5, color: tokens.faint, marginTop: 4 }}>{t("Contract, ID document, certificates (PDF, JPG — max 5MB)")}</div>
              <input ref={fileInputRef} type="file" style={{ display: "none" }} onChange={(e) => { if (e.target.files[0]) addMockFile(e.target.files[0].name); }} />
            </div>
            {form.documents.length === 0 ? (
              <div style={{ fontSize: 12.5, color: tokens.faint, textAlign: "center" }}>{t("No documents added yet.")}</div>
            ) : (
              form.documents.map((d) => (
                <div key={d.name} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 10px", background: tokens.bg, borderRadius: 8, marginBottom: 6 }}>
                  <FileText size={15} color={tokens.inkSoft} />
                  <div style={{ flex: 1, fontSize: 13, color: tokens.ink }}>{d.name}</div>
                  <Badge tone="success">{t("Uploaded")}</Badge>
                  <span style={{ fontSize: 12, color: tokens.faint }}>{d.size}</span>
                  <Trash2 size={14} color={tokens.faint} style={{ cursor: "pointer" }} onClick={() => removeFile(d.name)} />
                </div>
              ))
            )}
          </div>
        )}

        {step === 5 && (
          <div>
            <h2 style={{ fontSize: 14.5, fontWeight: 600, marginTop: 0, marginBottom: 16 }}>{t("Review")}</h2>
            {[
              { title: "Personal", onEdit: () => setStep(1), rows: [[t("Full name"), form.fullName || "—"], [t("Date of birth"), form.dob || "—"], [t("Gender"), form.gender ? t(form.gender) : "—"], [t("Phone"), form.phone || "—"], [t("Email"), form.email || "—"], [t("Address"), form.address || "—"]] },
              { title: "Employment", onEdit: () => setStep(2), rows: [[t("Department"), form.dept || "—"], [t("Position"), form.position || "—"], [t("Manager"), form.manager || "—"], [t("Type"), t(form.type)], [t("Status"), t(form.status)], [t("Join date"), form.joinDate || "—"]] },
              { title: "Compensation", onEdit: () => setStep(3), rows: [[t("Basic salary"), form.salary ? "Rp " + form.salary : "—"], [t("Allowances"), form.allowances ? "Rp " + form.allowances : "—"], [t("Payroll frequency"), t(form.payFrequency)]] },
              { title: "Documents", onEdit: () => setStep(4), rows: [[t("Files"), t("{n} file(s)", { n: form.documents.length })]] },
            ].map((section) => (
              <div key={section.title} style={{ marginBottom: 18, paddingBottom: 18, borderBottom: `1px solid ${tokens.border}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 600, color: tokens.ink }}>{t(section.title)}</span>
                  <span style={{ fontSize: 12.5, color: tokens.primary, fontWeight: 600, cursor: "pointer" }} onClick={section.onEdit}>{t("Edit")}</span>
                </div>
                <DL rows={section.rows} />
              </div>
            ))}
          </div>
        )}
      </Card>

      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 20 }}>
        <div>
          {step > 1 && <Button variant="secondary" icon={ArrowLeft} onClick={back}>{t("Back")}</Button>}
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <Button variant="ghost">{t("Save draft")}</Button>
          {step < 5 ? (
            <Button onClick={next} style={{ padding: "8px 12px" }}>{t("Continue")} <ArrowRight size={14} style={{ marginLeft: 2 }} /></Button>
          ) : (
            <Button onClick={commit}>{t("Create employee")}</Button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ================================================================== */
/* ATTENDANCE — shared display primitives                              */
/* ================================================================== */

function StatusPill({ status }) {
  return <Badge tone={attendanceStatusTone(status)}>{t(status)}</Badge>;
}

// Risk sits next to status but is never folded into it. A clean record
// recedes to quiet text so the flagged ones are the only thing that
// catches the eye in a long table.
function RiskChip({ level, size }) {
  if (!level || level === RISK.VALID) {
    return <span style={{ fontSize: size === "sm" ? 11.5 : 12, color: tokens.faint }}>{t("Valid")}</span>;
  }
  return <Badge tone={RISK_TONE[level]}>{t(RISK_LABEL[level])}</Badge>;
}

function MethodTag({ method, showIcon }) {
  if (!method) return <span style={{ fontSize: 12.5, color: tokens.faint }}>—</span>;
  const Icon = METHOD_ICON[method];
  return (
    <span style={{ fontSize: 12.5, color: tokens.inkSoft, display: "inline-flex", alignItems: "center", gap: 5, whiteSpace: "nowrap" }}>
      {showIcon && Icon && <Icon size={13} color={tokens.faint} />}
      {t(METHOD_LABEL[method] || method)}
    </span>
  );
}

function LocationCell({ loc }) {
  if (!loc) return <span style={{ fontSize: 13, color: tokens.faint }}>{t("Not captured")}</span>;
  const unregistered = loc.registered === false && !loc.trip;
  return (
    <span style={{ fontSize: 13, color: tokens.inkSoft, display: "inline-flex", alignItems: "center", gap: 5 }}>
      {locLabel(loc)}
      {unregistered && (
        <span title={t("Not in the registered location list — allowed, but worth a look")}>
          <AlertTriangle size={12} color={tokens.warning} />
        </span>
      )}
    </span>
  );
}

/* Exception-first ordering (spec §2, §33). The number is a priority, not
   a score — lower sorts higher. Everything a person must act on today
   ranks above everything that merely happened. */
function attnSeverity(r) {
  if (r.risk.level === RISK.HIGH_RISK) return 0;
  if (r.status === ATT_STATUS.NOT_CLOCKED_IN && !r.future) return 1;
  if (r.risk.level === RISK.SUSPICIOUS) return 2;
  if (r.status === ATT_STATUS.ABSENT) return 3;
  if (r.status === ATT_STATUS.INCOMPLETE) return 4;
  if (r.correction.state === CORRECTION_STATE.PENDING) return 5;
  if (r.risk.level === RISK.REVIEW) return 6;
  if (r.status === ATT_STATUS.EARLY_LEAVE) return 7;
  if (r.status === ATT_STATUS.LATE) return 8;
  if ([ATT_STATUS.FIELD_WORK, ATT_STATUS.BUSINESS_TRIP].includes(r.status)) return 9;
  if (r.status === ATT_STATUS.PRESENT) return 10;
  return 11;
}
const ATT_SORTERS = {
  exception: (a, b) =>
    attnSeverity(a) - attnSeverity(b) || b.lateMin - a.lateMin ||
    b.date.localeCompare(a.date) || (a._name || "").localeCompare(b._name || ""),
  name: (a, b) => (a._name || "").localeCompare(b._name || "") || b.date.localeCompare(a.date),
  date: (a, b) => b.date.localeCompare(a.date) || (a._name || "").localeCompare(b._name || ""),
  latest: (a, b) => (parseHHMM(b.clockIn) || 0) - (parseHHMM(a.clockIn) || 0),
};

// Has the working day finished? Drives "missing check-out" — someone still
// at their desk at 14:20 is not a missing check-out.
function dayElapsed(rec) {
  if (rec.date < TODAY_STR) return true;
  if (rec.date > TODAY_STR) return false;
  const sched = WORK_SCHEDULES[rec.scheduleKey] || WORK_SCHEDULES["Head Office"];
  return SIM_NOW_MIN >= toMinutes(sched.end);
}

/* Recomputes the derived half of a record after its times change — used
   by both the simulated device events and by approving a correction, so
   the two paths can never drift apart. */
function recomputeRecord(rec, times) {
  const sched = WORK_SCHEDULES[rec.scheduleKey] || WORK_SCHEDULES["Head Office"];
  const clockIn = times.clockIn !== undefined ? times.clockIn : rec.clockIn;
  const clockOut = times.clockOut !== undefined ? times.clockOut : rec.clockOut;
  const inMin = parseHHMM(clockIn), outMin = parseHHMM(clockOut);
  const arrival = computeArrival(sched, inMin);
  const dep = computeDeparture(sched, outMin);
  const isToday = rec.date === TODAY_STR;

  const stillWorking = isToday && SIM_NOW_MIN < toMinutes(sched.end);

  let status;
  if ([ATT_STATUS.FIELD_WORK, ATT_STATUS.BUSINESS_TRIP, ATT_STATUS.ON_LEAVE, ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY].includes(rec.status)) {
    status = rec.status; // a corrected time doesn't turn a field day into an office day
  } else if (inMin == null) status = isToday ? ATT_STATUS.NOT_CLOCKED_IN : ATT_STATUS.ABSENT;
  else if (outMin == null && !stillWorking) status = ATT_STATUS.INCOMPLETE;
  else if (arrival.late) status = ATT_STATUS.LATE;
  else if (outMin != null && dep.earlyLeaveMin >= ATTENDANCE_POLICY.earlyLeaveStatusMin) status = ATT_STATUS.EARLY_LEAVE;
  else status = ATT_STATUS.PRESENT;

  return {
    clockIn, clockOut, status,
    lateMin: arrival.lateMin, earlyLeaveMin: dep.earlyLeaveMin, otMin: dep.otMin,
    workedMin: computeWorkedMinutes(sched, rec.date, inMin, outMin),
    mealEligible: inMin != null ? mealEligibleFor(inMin) : null,
  };
}

/* ------------------------------------------------------------------ */
/* Shared attendance table                                             */
/* ------------------------------------------------------------------ */
const cellTxt = (v) => <span style={{ fontSize: 13, color: tokens.inkSoft }}>{v}</span>;
const cellNum = (v, tone) => <span style={{ fontSize: 13, color: tone || tokens.inkSoft, fontVariantNumeric: "tabular-nums" }}>{v}</span>;
const DASH = <span style={{ color: tokens.faint }}>—</span>;

const ATT_COLUMNS = {
  employee: { header: "Employee", cell: (r) => (
    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
      <Avatar name={r._name} color={colorFor(r._colorSeed)} soft={colorSoftFor(r._colorSeed)} size={30} />
      <div>
        <div style={{ fontSize: 13.5, fontWeight: 600, color: tokens.ink }}>{r._name}</div>
        <div style={{ fontSize: 12, color: tokens.faint }}>{r._position}</div>
      </div>
    </div>
  ) },
  date: { header: "Date", cell: (r) => (
    <div>
      <div style={{ fontSize: 13, color: tokens.ink, fontVariantNumeric: "tabular-nums" }}>{fmtDateShort(r.date)}</div>
      <div style={{ fontSize: 11.5, color: tokens.faint }}>
        {new Date(r.date + "T00:00:00").toLocaleDateString(dateLocale(), { weekday: "short" })}
      </div>
    </div>
  ) },
  department: { header: "Department", cell: (r) => cellTxt(r._dept) },
  location: { header: "Work location", cell: (r) => <LocationCell loc={r.workLocation} /> },
  method: { header: "Method", cell: (r) => <MethodTag method={r.method} showIcon /> },
  in: { header: "Clock in", cell: (r) => cellNum(r.clockIn || "—", r.clockIn ? undefined : tokens.faint) },
  out: { header: "Clock out", cell: (r) => cellNum(r.clockOut || "—", r.clockOut ? undefined : tokens.faint) },
  hours: { header: "Working hours", cell: (r) => cellNum(r.workedMin != null ? formatDuration(r.workedMin) : "—", r.workedMin == null ? tokens.faint : undefined) },
  late: { header: "Late", cell: (r) => (r.lateMin > 0 ? cellNum("+" + fmtDelta(r.lateMin), tokens.warning) : DASH) },
  early: { header: "Early leave", cell: (r) => (r.earlyLeaveMin > 0 ? cellNum("−" + fmtDelta(r.earlyLeaveMin), tokens.warning) : DASH) },
  ot: { header: "Overtime", cell: (r) => (r.otMin > 0 ? cellNum("+" + fmtDelta(r.otMin)) : DASH) },
  meal: { header: "Meal allowance", cell: (r) => (
    r.mealEligible == null ? DASH
      : <span style={{ fontSize: 12.5, color: r.mealEligible ? tokens.inkSoft : tokens.warning }}>
          {r.mealEligible ? t("Eligible") : t("Not eligible")}
        </span>
  ) },
  status: { header: "Status", cell: (r) => <StatusPill status={r.status} /> },
  risk: { header: "Risk", cell: (r) => <RiskChip level={r.risk.level} /> },
  correction: { header: "Correction", cell: (r) => (
    r.correction.state === CORRECTION_STATE.NONE ? DASH
      : <Badge tone={statusTone(r.correction.state)}>{t(r.correction.state)}</Badge>
  ) },
  actions: { header: "", align: "right", cell: (r, open) => {
    const flagged = attnSeverity(r) <= 6;
    return flagged
      ? <Button variant="ghost" size="sm" onClick={() => open()}>{t("Review")}</Button>
      : <MoreHorizontal size={16} color={tokens.faint} style={{ cursor: "pointer" }} onClick={() => open()} />;
  } },
};

/* Status, Risk and Actions are pinned to the right edge. In a 14-column
   table they would otherwise be the first things to scroll out of view —
   and they are the whole reason an HR user is looking at the row. */
const ATT_STICKY = { status: { right: 158, width: 104 }, risk: { right: 62, width: 96 }, actions: { right: 0, width: 62 } };

function AttendanceTable({ rows, columns, onRowClick, emptyState, minWidth }) {
  if (!rows.length) return emptyState || <EmptyState icon={Clock} title={t("No records")} subtitle={t("Nothing to show here.")} />;
  const cols = columns.map((id) => ({ id, ...ATT_COLUMNS[id], header: t(ATT_COLUMNS[id].header) })).filter((c) => c.cell);
  // Only pin when all three are present and there is enough width to scroll.
  const pinned = ["status", "risk", "actions"].every((id) => columns.includes(id));
  const stickyFor = (id) => (pinned && ATT_STICKY[id] ? ATT_STICKY[id] : null);

  return (
    <>
      <div className="hris-att-table" style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", minWidth: minWidth || 1040, borderCollapse: "collapse" }}>
          <thead>
            <tr style={{ borderBottom: `1px solid ${tokens.border}` }}>
              {cols.map((c) => {
                const st = stickyFor(c.id);
                return (
                  <th
                    key={c.id}
                    className={st ? "hris-att-sticky-head" : undefined}
                    style={{
                      textAlign: c.align || "left", fontSize: 11.5, fontWeight: 600, color: tokens.faint,
                      textTransform: "uppercase", letterSpacing: 0.3, padding: "10px 12px", whiteSpace: "nowrap",
                      ...(st ? { position: "sticky", right: st.right, width: st.width, minWidth: st.width, zIndex: 2 } : null),
                      ...(c.id === "status" && st ? { borderLeft: `1px solid ${tokens.border}` } : null),
                    }}
                  >{c.header}</th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr
                key={r.id}
                className="hris-att-row"
                onClick={() => onRowClick && onRowClick(r)}
                style={{ borderBottom: `1px solid ${tokens.border}`, cursor: onRowClick ? "pointer" : "default" }}
              >
                {cols.map((c) => {
                  const st = stickyFor(c.id);
                  return (
                    <td
                      key={c.id}
                      className={st ? "hris-att-sticky" : undefined}
                      onClick={c.id === "actions" ? (ev) => ev.stopPropagation() : undefined}
                      style={{
                        padding: "10px 12px", textAlign: c.align || "left",
                        // Times and durations must never wrap; names and places may,
                        // which keeps the table narrow enough to stay readable.
                        whiteSpace: ["department", "location"].includes(c.id) ? "normal" : "nowrap",
                        ...(st ? { position: "sticky", right: st.right, width: st.width, minWidth: st.width, zIndex: 1 } : null),
                        ...(c.id === "status" && st ? { borderLeft: `1px solid ${tokens.border}` } : null),
                      }}
                    >
                      {c.cell(r, () => onRowClick && onRowClick(r))}
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Phones get a stacked card per record — a 13-column table behind a
          horizontal scrollbar is not a mobile experience. */}
      <div className="hris-att-cards" style={{ display: "none" }}>
        {rows.map((r) => {
          const showEmployee = columns.includes("employee");
          return (
            <div
              key={r.id}
              onClick={() => onRowClick && onRowClick(r)}
              style={{ padding: "12px 16px", borderBottom: `1px solid ${tokens.border}`, cursor: onRowClick ? "pointer" : "default" }}
            >
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                {showEmployee && <Avatar name={r._name} color={colorFor(r._colorSeed)} soft={colorSoftFor(r._colorSeed)} size={34} />}
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13.5, fontWeight: 600, color: tokens.ink }}>
                    {showEmployee ? r._name : fmtDateShort(r.date)}
                  </div>
                  <div style={{ fontSize: 12, color: tokens.muted }}>
                    {showEmployee
                      ? `${r._position} · ${fmtDateShort(r.date)}`
                      : new Date(r.date + "T00:00:00").toLocaleDateString(dateLocale(), { weekday: "long" })}
                  </div>
                </div>
                <StatusPill status={r.status} />
              </div>

              <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 8, marginTop: 10 }}>
                {[[t("In"), r.clockIn || "—"], [t("Out"), r.clockOut || "—"], [t("Hours"), r.workedMin != null ? formatDuration(r.workedMin) : "—"]].map(([l, v]) => (
                  <div key={l}>
                    <div style={{ fontSize: 11, color: tokens.faint }}>{l}</div>
                    <div style={{ fontSize: 13, color: tokens.inkSoft, fontVariantNumeric: "tabular-nums" }}>{v}</div>
                  </div>
                ))}
              </div>

              <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
                <MethodTag method={r.method} showIcon />
                {r.workLocation && <span style={{ fontSize: 12, color: tokens.muted }}>{locLabel(r.workLocation)}</span>}
                <span style={{ marginLeft: "auto" }}><RiskChip level={r.risk.level} size="sm" /></span>
              </div>

              {(r.lateMin > 0 || r.earlyLeaveMin > 0 || r.otMin > 0 || r.correction.state !== CORRECTION_STATE.NONE) && (
                <div style={{ display: "flex", gap: 12, marginTop: 8, fontSize: 12, color: tokens.muted, flexWrap: "wrap" }}>
                  {r.lateMin > 0 && <span>Late +{fmtDelta(r.lateMin)}</span>}
                  {r.earlyLeaveMin > 0 && <span>Early −{fmtDelta(r.earlyLeaveMin)}</span>}
                  {r.otMin > 0 && <span>OT +{fmtDelta(r.otMin)}</span>}
                  {r.correction.state !== CORRECTION_STATE.NONE && <span>{t("Correction")} {t(r.correction.state).toLowerCase()}</span>}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </>
  );
}

/* ================================================================== */
/* ATTENDANCE — detail drawer, evidence and risk (spec §10, §11, §37)  */
/* ================================================================== */

// The four sanctioned framings from §37. Nothing here accuses anyone: the
// system reports what the signals said and asks a person to look.
const RISK_HEADLINE = {
  VALID: "No anomalies detected",
  REVIEW: "Review recommended",
  SUSPICIOUS: "Attendance anomaly",
  HIGH_RISK: "High-risk attendance",
};
const RISK_INTRO = {
  VALID: "Every signal on this record is within the expected range.",
  REVIEW: "One signal needs a human check before this record is finalised.",
  SUSPICIOUS: "Risk detected — one or more signals are outside the expected range.",
  HIGH_RISK: "Several signals on this record need review before it is finalised.",
};
const RISK_RECOMMENDATION = {
  VALID: "No action needed. This record can be finalised in the weekly review.",
  REVIEW: "Confirm with the employee or their supervisor before the weekly lock.",
  SUSPICIOUS: "Hold this record. Compare it with the person's usual pattern and the device and location evidence, then accept it, request a correction, or escalate.",
  HIGH_RISK: "Do not finalise yet. Escalate to HR for a documented conversation with the employee before the weekly lock. These signals are not proof on their own.",
};
const RISK_ACCENT = { VALID: tokens.success, REVIEW: tokens.info, SUSPICIOUS: tokens.warning, HIGH_RISK: tokens.danger };
const RISK_SOFT = { VALID: tokens.successSoft, REVIEW: tokens.infoSoft, SUSPICIOUS: tokens.warningSoft, HIGH_RISK: tokens.dangerSoft };
const RISK_RING = { VALID: tokens.successRing, REVIEW: tokens.infoRing, SUSPICIOUS: tokens.warningRing, HIGH_RISK: tokens.dangerRing };

const SIGNAL_MARKER = {
  pass: { label: "Normal", color: tokens.success },
  attention: { label: "Attention", color: tokens.warning },
  na: { label: "No data", color: tokens.faint },
};

// The seven signals, always in the same order and always all seven, so a
// missing check reads as "we didn't get this" rather than disappearing.
function signalRows(rec) {
  const s = (rec.risk && rec.risk.signals) || {};
  // label + value are translation keys; the row renderer runs them through t().
  const mk = (label, value, state) => ({ label, value, state });
  const rows = [];

  rows.push(s.gpsAccuracyM != null
    ? mk("GPS accuracy", "±" + s.gpsAccuracyM + " m", s.gpsAccuracyM > 50 ? "attention" : "pass")
    : mk("GPS accuracy", "Not captured", "na"));

  rows.push(s.faceMatch != null
    ? mk("Face verification", t("{n}% match", { n: Math.round(s.faceMatch * 100) }), s.faceMatch < 0.8 ? "attention" : "pass")
    : mk("Face verification", "Not captured", "na"));

  rows.push(s.deviceTrusted != null
    ? mk("Device", s.deviceTrusted ? "Registered device" : "Unregistered device", s.deviceTrusted ? "pass" : "attention")
    : mk("Device", rec.method === METHOD.FINGERPRINT ? "Fixed reader" : "Not captured", rec.method === METHOD.FINGERPRINT ? "pass" : "na"));

  rows.push(rec.workLocation
    ? mk("Location", rec.workLocation.registered === false && !rec.workLocation.trip ? t("Unregistered location") : locLabel(rec.workLocation),
         rec.workLocation.registered === false && !rec.workLocation.trip ? "attention" : "pass")
    : mk("Location", "Not captured", "na"));

  rows.push(s.impossibleTravel != null
    ? mk("Impossible travel", s.impossibleTravel ? "Detected" : "None detected", s.impossibleTravel ? "attention" : "pass")
    : mk("Impossible travel", "Not evaluated", "na"));

  rows.push(s.mockGps != null
    ? mk("Mock GPS", s.mockGps ? "Reported by the device" : "Not detected", s.mockGps ? "attention" : "pass")
    : mk("Mock GPS", "Not evaluated", "na"));

  rows.push(mk("Timestamp", s.timestampOk === false ? "Device clock differs from server" : "Server-authoritative",
    s.timestampOk === false ? "attention" : "pass"));

  return rows;
}

function evidenceRows(rec) {
  const ev = rec.evidence || {};
  const loc = rec.workLocation;
  const coords = loc && loc.lat != null ? `${loc.lat.toFixed(5)}, ${loc.lng.toFixed(5)}` : t("Not captured");
  const acc = loc && loc.accuracyM != null ? `±${loc.accuracyM} m` : t("Not captured");
  const face = ev.faceMatchPct != null ? t("{n}% match", { n: ev.faceMatchPct }) : t("Not captured");
  const liveness = ev.livenessOk === false ? t("Did not complete") : t("Passed");

  switch (rec.method) {
    case METHOD.FINGERPRINT:
      return [
        [t("Captured by"), t("Fingerprint reader")],
        [t("Device"), ev.deviceLabel || "—"],
        [t("Placement"), ev.devicePlacement || "—"],
        [t("Fingerprint ID"), ev.fingerId || "—"],
        [t("Enrolment quality"), ev.enrolQuality ? t(ev.enrolQuality) : "—"],
        [t("Last device sync"), ev.syncedAt ? fmtDateTime(ev.syncedAt) : "—"],
      ];
    case METHOD.MOBILE_GPS:
      return [
        [t("Captured by"), t("Mobile app")],
        [t("Device"), ev.deviceLabel ? `${ev.deviceLabel} · ${ev.deviceOs || ""}`.trim() : "—"],
        [t("Device registration"), ev.deviceTrusted === false ? t("Not registered to this employee") : t("Registered")],
        [t("GPS coordinates"), coords],
        [t("GPS accuracy"), acc],
        [t("Captured at"), ev.capturedAt || "—"],
        [t("Face verification"), face],
        [t("Liveness"), liveness],
      ];
    case METHOD.FIELD_WORK:
      return [
        [t("Captured by"), t("Mobile app — field visit")],
        [t("Field location"), loc ? locLabel(loc) : "—"],
        [t("Location status"), loc && loc.registered ? t("Registered location") : t("Unregistered location")],
        [t("GPS coordinates"), coords],
        [t("GPS accuracy"), acc],
        [t("Captured at"), ev.capturedAt || "—"],
        [t("Purpose"), ev.purpose || "—"],
        [t("Customer"), ev.customer || "—"],
      ];
    case METHOD.HADIR:
      return [
        [t("Source"), "Hadir"],
        [t("Imported at"), ev.importedAt ? fmtDateTime(ev.importedAt) : "—"],
        [t("Sync status"), ev.syncStatus ? t(ev.syncStatus) : "—"],
        [t("Note"), ev.note ? t(ev.note) : t(HADIR_SOURCE.note)],
      ];
    default:
      return [[t("Captured by"), t("No attendance captured for this day")]];
  }
}

