  if (!record) return null;
  const emp = employee || employeeById(record.employeeId);
  const risk = record.risk || emptyRisk();
  const showEvidence = canSeeEvidence(role);
  const showRisk = canSeeRisk(role);
  // Everyone can see their own meal-allowance eligibility; otherwise only the
  // payroll-relevant roles. viewerId is the real signed-in id (or the demo
  // stand-in when HR previews another role).
  const showMeal = canSeeAllowance(role) || record.employeeId === (viewerId || VIEWER_FOR_ROLE[role] || SELF.id);
