/* ================================================================== */
/* ATTENDANCE — overview                                               */
/* ================================================================== */

function decorateRecord(rec) {
  const e = employeeById(rec.employeeId);
  return {
    ...rec,
    _name: e.name, _dept: e.dept, _position: e.position, _colorSeed: e.colorSeed || 0,
    _workday: ![ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY].includes(rec.status),
  };
}

/* The ten questions the overview has to answer at a glance (spec §2).
   Each is a filter, not just a number — clicking one narrows the table
   below to exactly the rows it counted. */
const SUMMARY_METRICS = [
  { key: "present", labelKey: "Present", pred: (r) => [ATT_STATUS.PRESENT, ATT_STATUS.EARLY_LEAVE, ATT_STATUS.INCOMPLETE].includes(r.status) },
  { key: "late", labelKey: "Late", pred: (r) => r.status === ATT_STATUS.LATE },
  { key: "missing_in", labelKey: "Missing check-in", pred: (r) => r._workday && !r.clockIn && r.status !== ATT_STATUS.ON_LEAVE },
  { key: "missing_out", labelKey: "Missing check-out", pred: (r) => r._workday && !!r.clockIn && !r.clockOut && dayElapsed(r) },
  { key: "leave", labelKey: "Leave", pred: (r) => r.status === ATT_STATUS.ON_LEAVE },
  { key: "field", labelKey: "Field work", pred: (r) => [ATT_STATUS.FIELD_WORK, ATT_STATUS.BUSINESS_TRIP].includes(r.status) },
  { key: "early", labelKey: "Early leave", pred: (r) => r.earlyLeaveMin >= ATTENDANCE_POLICY.earlyLeaveStatusMin },
  { key: "flagged", labelKey: "Flagged", pred: (r) => r.risk.level !== RISK.VALID },
  { key: "overtime", labelKey: "Overtime", pred: (r) => r.otMin > 0 },
  { key: "correction", labelKey: "Correction pending", pred: (r) => r.correction.state === CORRECTION_STATE.PENDING },
];

function SummaryMetricRow({ metrics, active, onPick }) {
  return (
    <div className="hris-att-metrics" style={{ background: tokens.surface, border: `1px solid ${tokens.border}`, borderRadius: 10, overflow: "hidden" }}>
      {metrics.map((m, i) => {
        const on = active === m.key;
        return (
          <button
            key={m.key} type="button" aria-pressed={on} onClick={() => onPick(m.key)}
            style={{
              textAlign: "left", cursor: "pointer", font: "inherit", fontFamily: fontStack,
              padding: "12px 14px", border: "none",
              borderLeft: i > 0 ? `1px solid ${tokens.border}` : "none",
              background: on ? tokens.primarySoft : tokens.surface,
            }}
          >
            <div style={{ fontSize: 20, fontWeight: 600, letterSpacing: -0.4, fontVariantNumeric: "tabular-nums", color: m.value === 0 ? tokens.faint : tokens.ink }}>
              {m.value}
            </div>
            <div style={{ fontSize: 11.5, marginTop: 2, color: on ? tokens.primary : tokens.muted, fontWeight: on ? 600 : 400 }}>
              {t(m.labelKey)}
            </div>
          </button>
        );
      })}
    </div>
  );
}

function PeriodToggle({ value, onChange }) {
  const opts = [["today", t("Today")], ["week", t("This Week")], ["month", t("This Month")]];
  return (
    <div style={{ display: "inline-flex", border: `1px solid ${tokens.borderStrong}`, borderRadius: 8, overflow: "hidden" }}>
      {opts.map(([k, label], i) => (
        <button
          key={k} type="button" onClick={() => onChange(k)}
          style={{
            font: "inherit", fontFamily: fontStack, fontSize: 13, fontWeight: value === k ? 600 : 500,
            cursor: "pointer", padding: "7px 12px", border: "none",
            borderLeft: i > 0 ? `1px solid ${tokens.borderStrong}` : "none",
            background: value === k ? tokens.primarySoft : tokens.surface,
            color: value === k ? tokens.primary : tokens.inkSoft,
          }}
        >{label}</button>
      ))}
    </div>
  );
}

function periodRange(date, mode) {
  if (mode === "today") return { from: date, to: date, days: [date] };
  if (mode === "week") {
    const w = weeklyPeriod(date);
    return { from: w.startDate, to: w.endDate, days: w.days };
  }
  const d = new Date(date + "T00:00:00");
  const first = isoDate(new Date(d.getFullYear(), d.getMonth(), 1));
  const last = isoDate(new Date(d.getFullYear(), d.getMonth() + 1, 0));
  const days = [];
  let x = first;
  while (x <= last) { days.push(x); x = addDays(x, 1); }
  return { from: first, to: last, days };
}
function shiftDate(date, mode, dir) {
  if (mode === "today") return addDays(date, dir);
  if (mode === "week") return addDays(date, dir * 7);
  return addMonths(date, dir);
}
function periodLabel(range, mode) {
  if (mode === "today") return fmtDayLabel(range.from);
  if (mode === "month") return new Date(range.from + "T00:00:00").toLocaleDateString(dateLocale(), { month: "long", year: "numeric" });
  return weeklyPeriod(range.from).label;
}

function AttendanceOverview({ session, roster, getRecord, onOpenRecord, initialFilter }) {
  const [date, setDate] = useState(TODAY_STR);
  const [mode, setMode] = useState("today");
  const [filter, setFilter] = useState(initialFilter || "all");
  const [dept, setDept] = useState("");
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState("exception");
  const [page, setPage] = useState(1);
  const pageSize = 12;

  const range = useMemo(() => periodRange(date, mode), [date, mode]);
  const label = useMemo(() => periodLabel(range, mode), [range, mode, LANG]);

  const records = useMemo(() => {
    const out = [];
    for (const emp of roster) {
      for (const d of range.days) {
        if (d > TODAY_STR) continue;
        const rec = getRecord(emp.id, d);
        if ([ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY].includes(rec.status)) continue;
        out.push(decorateRecord(rec));
      }
    }
    return out;
  }, [roster, range, getRecord]);

  const metrics = useMemo(
    () => SUMMARY_METRICS.map((m) => ({ ...m, value: records.filter(m.pred).length })),
    [records]
  );

  const filtered = useMemo(() => {
    let rows = records;
    const m = SUMMARY_METRICS.find((x) => x.key === filter);
    if (m) rows = rows.filter(m.pred);
    if (dept) rows = rows.filter((r) => r._dept === dept);
    const q = query.trim().toLowerCase();
    if (q) rows = rows.filter((r) => r._name.toLowerCase().includes(q) || r.employeeId.toLowerCase().includes(q));
    return rows.slice().sort(ATT_SORTERS[sort]);
  }, [records, filter, dept, query, sort]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
  const safePage = Math.min(page, totalPages);
  const pageRows = filtered.slice((safePage - 1) * pageSize, safePage * pageSize);

  const reset = (fn) => (...args) => { fn(...args); setPage(1); };
  const pickFilter = (key) => { setFilter((f) => (f === key ? "all" : key)); setPage(1); };

  // Non-working days produce no rows at all — say so plainly instead of
  // showing an empty table that reads like missing data.
  const probe = mode === "today" && roster[0] ? getRecord(roster[0].id, date) : null;
  const nonWorking = probe && [ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY].includes(probe.status);

  const columns = ["employee", ...(mode === "today" ? [] : ["date"]), "department", "location", "method",
    "in", "out", "hours", "late", "early", "ot",
    ...(canSeeAllowance(session.role) ? ["meal"] : []),
    "correction",
    "status", ...(canSeeRisk(session.role) ? ["risk"] : []),
    ...(canOpenDetail(session.role) ? ["actions"] : [])];

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 14 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
          <Button
            variant="secondary" size="sm" icon={ChevronLeft} style={{ width: 32, padding: 0 }}
            title={`Previous ${mode === "today" ? "day" : mode}`} ariaLabel={`Previous ${mode === "today" ? "day" : mode}`}
            onClick={reset(() => setDate(shiftDate(date, mode, -1)))}
          />
          <span style={{ fontSize: 14, fontWeight: 600, color: tokens.ink, minWidth: 210, textAlign: "center" }}>{label}</span>
          <Button
            variant="secondary" size="sm" icon={ChevronRight} style={{ width: 32, padding: 0 }}
            title={`Next ${mode === "today" ? "day" : mode}`} ariaLabel={`Next ${mode === "today" ? "day" : mode}`}
            onClick={reset(() => setDate(shiftDate(date, mode, 1)))}
          />
          <Button variant="secondary" size="sm" disabled={date === TODAY_STR} onClick={reset(() => setDate(TODAY_STR))}>{t("Today")}</Button>
          <input type="date" value={date} onChange={reset((e) => setDate(e.target.value || TODAY_STR))} style={{ ...inputStyle(false), width: 152 }} />
        </div>
        <PeriodToggle value={mode} onChange={reset(setMode)} />
      </div>

      <div style={{ marginBottom: 14 }}>
        <SummaryMetricRow metrics={metrics} active={filter} onPick={pickFilter} />
      </div>

      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 12, alignItems: "center" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, background: tokens.surface, border: `1px solid ${tokens.borderStrong}`, borderRadius: 8, padding: "7px 10px", flex: "1 1 240px", minWidth: 200 }}>
          <Search size={15} color={tokens.faint} />
          <input
            value={query} onChange={reset((e) => setQuery(e.target.value))}
            placeholder={t("Search by name or employee ID...")}
            style={{ border: "none", outline: "none", fontSize: 13.5, fontFamily: fontStack, flex: 1, background: "transparent" }}
          />
        </div>
        <Select value={dept} onChange={reset((e) => setDept(e.target.value))} style={{ width: 180 }}>
          <option value="">{t("All departments")}</option>
          {departments.map((d) => <option key={d} value={d}>{d}</option>)}
        </Select>
        <Select value={sort} onChange={reset((e) => setSort(e.target.value))} style={{ width: 190 }}>
          <option value="exception">{t("Sort: Exceptions first")}</option>
          <option value="name">{t("Sort: Name")}</option>
          <option value="latest">{t("Sort: Latest arrival")}</option>
        </Select>
        {filter !== "all" && (
          <button
            type="button" onClick={() => pickFilter(filter)}
            style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 12.5, fontWeight: 600, fontFamily: fontStack, color: tokens.primary, background: tokens.primarySoft, border: "none", borderRadius: 6, padding: "7px 10px", cursor: "pointer" }}
          >
            {t(SUMMARY_METRICS.find((m) => m.key === filter)?.labelKey)}
            <X size={13} />
          </button>
        )}
      </div>

      <div style={{ background: tokens.surface, border: `1px solid ${tokens.border}`, borderRadius: 10, overflow: "hidden" }}>
        {nonWorking ? (
          <EmptyState
            icon={CalendarDays}
            title={probe.status === ATT_STATUS.HOLIDAY ? `${t("Holiday")} — ${probe.holidayName || t("no scheduled work")}` : t("Weekend — no scheduled work")}
            subtitle={t("{day} is not a working day at either site.", { day: fmtDayLabel(date) })}
          />
        ) : records.length === 0 ? (
          <EmptyState icon={CalendarDays} title={t("Nothing recorded yet")} subtitle={t("There are no attendance records for {label}.", { label })} />
        ) : filtered.length === 0 ? (
          <EmptyState
            icon={SlidersHorizontal} title={t("No matching records")}
            subtitle={t("No attendance records match this filter for {label}.", { label })}
            action={<Button variant="secondary" onClick={() => { setFilter("all"); setDept(""); setQuery(""); setPage(1); }}>{t("Clear filters")}</Button>}
          />
        ) : (
          <>
            <AttendanceTable rows={pageRows} columns={columns} onRowClick={canOpenDetail(session.role) ? onOpenRecord : null} minWidth={1040} />
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 16px", borderTop: `1px solid ${tokens.border}` }}>
              <span style={{ fontSize: 12.5, color: tokens.muted }}>
                {t("Showing {a}–{b} of {n}", { a: (safePage - 1) * pageSize + 1, b: Math.min(safePage * pageSize, filtered.length), n: filtered.length })}
              </span>
              <div style={{ display: "flex", gap: 6 }}>
                <Button variant="secondary" size="sm" disabled={safePage === 1} onClick={() => setPage(safePage - 1)}>{t("Previous")}</Button>
                <Button variant="secondary" size="sm" disabled={safePage === totalPages} onClick={() => setPage(safePage + 1)}>{t("Next")}</Button>
              </div>
            </div>
          </>
        )}
      </div>

      {session.role === "Director" && (
        <p style={{ fontSize: 12, color: tokens.muted, marginTop: 12 }}>
          You are seeing workforce totals. Individual attendance evidence is restricted to HR and the
          employee's own line management.
        </p>
      )}
    </div>
  );
}

/* ================================================================== */
/* ATTENDANCE — my attendance                                          */
/* ================================================================== */

const SIM_EVENT_TIMES = {
  "Head Office": { in: "08:26", out: "17:41", lat: -6.19501, lng: 106.82290 },
  "Warehouse": { in: "07:58", out: "17:04", lat: -6.10295, lng: 106.88950 },
};

function makeDeviceEvent(emp, action, sched, source) {
  const t = action === "CHECK_IN" ? SIM_EVENT_TIMES[sched.key].in : SIM_EVENT_TIMES[sched.key].out;
  const fingerprint = source === METHOD.FINGERPRINT;
  return {
    id: `EVT-${emp.id}-${action}-${TODAY_STR}`,
    employeeId: emp.id, date: TODAY_STR, action, source,
    at: t,
    deviceId: fingerprint ? sched.deviceId : mobileDeviceFor(emp.id).id,
    deviceLabel: fingerprint ? deviceLabelFor(sched.deviceId) : mobileDeviceFor(emp.id).label,
    simulated: true,
  };
}

/* Folds simulated device events into a generated record. The UI never
   writes a time directly — it appends an event and the engine decides what
   that event means, which is how the real device feed will work. */
function applyEvents(rec, events) {
  if (!events || !events.length) return rec;
  if ([ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY, ATT_STATUS.ON_LEAVE].includes(rec.status)) return rec;
  const mine = events.filter((e) => e.employeeId === rec.employeeId && e.date === rec.date)
    .sort((a, b) => a.at.localeCompare(b.at));
  if (!mine.length) return rec;

  let out = rec;
  for (const e of mine) {
    if (e.action === "CHECK_IN" && !out.clockIn) {
      const sched = WORK_SCHEDULES[out.scheduleKey];
      const derived = recomputeRecord(out, { clockIn: e.at });
      out = {
        ...out, ...derived,
        method: e.source,
        workLocation: buildLocation(e.source, sched, out.date, { accuracyM: 12 }),
        evidence: { ...buildEvidence(e.source, sched, employeeById(out.employeeId), out.date, { capturedAt: e.at, faceMatch: 0.97, liveness: true }), simulatedEvent: true },
        risk: scoreRisk(e.source === METHOD.FINGERPRINT ? {} : { gpsAccuracyM: 12, mockGps: false, deviceTrusted: true, faceMatch: 0.97, liveness: true, timestampOk: true }),
        source: "simulated",
      };
    } else if (e.action === "CHECK_OUT" && out.clockIn && !out.clockOut) {
      out = { ...out, ...recomputeRecord(out, { clockOut: e.at }), source: "simulated" };
    }
  }
  return out;
}

function MyAttendance({ session, viewer, getRecord, appendEvent, onOpenRecord, onOpenCorrection, isLockedDate }) {
  const [month, setMonth] = useState(TODAY_STR.slice(0, 7));
  const [confirm, setConfirm] = useState(null);
  const [sort, setSort] = useState("date");

  const sched = scheduleForEmployee(viewer);
  const today = getRecord(viewer.id, TODAY_STR);
  const range = monthRangeOf(month, TODAY_STR);

  const records = useMemo(() => {
    const out = [];
    let d = range.from;
    while (d <= range.to) { out.push(decorateRecord(getRecord(viewer.id, d))); d = addDays(d, 1); }
    return out.reverse();
  }, [viewer.id, range.from, range.to, getRecord]);

  const workRecords = records.filter((r) => r._workday);
  const summary = monthSummary(records);

  const canCheckIn = !today.clockIn && ![ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY, ATT_STATUS.ON_LEAVE].includes(today.status);
  const canCheckOut = !!today.clockIn && !today.clockOut;
  const workedSoFar = today.clockIn
    ? computeWorkedMinutes(sched, TODAY_STR, parseHHMM(today.clockIn), parseHHMM(today.clockOut) || SIM_NOW_MIN)
    : 0;

  const monthOptions = useMemo(() => {
    const out = [];
    let k = TODAY_STR.slice(0, 7);
    for (let i = 0; i < 6; i++) {
      out.push({ key: k, label: new Date(k + "-01T00:00:00").toLocaleDateString(dateLocale(), { month: "long", year: "numeric" }) });
      k = addMonths(k + "-01", -1).slice(0, 7);
    }
    return out;
  }, [LANG]);

  const confirmCopy = {
    in: { title: "Simulate a fingerprint check-in?", body: `This appends a check-in event as if ${deviceLabelFor(sched.deviceId)} had pushed it at ${SIM_EVENT_TIMES[sched.key].in}. It is a demo event, not a real device read.` },
    "in-mobile": { title: "Simulate a mobile check-in?", body: `This appends a mobile check-in at ${SIM_EVENT_TIMES[sched.key].in} with a simulated in-area GPS fix and a pending selfie reference. Demo only.` },
    out: { title: "Simulate a fingerprint check-out?", body: `This appends a check-out event at ${SIM_EVENT_TIMES[sched.key].out} against today's open record. Demo only.` },
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <Card>
        <div style={{ padding: "16px 18px 6px", display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
          <div>
            <div style={{ fontSize: 14.5, fontWeight: 600, color: tokens.ink }}>{t("Today")}</div>
            <div style={{ fontSize: 12.5, color: tokens.muted, marginTop: 2 }}>{todayLabel()}</div>
          </div>
          <div style={{ fontSize: 12.5, color: tokens.muted, textAlign: "right" }}>
            <div>{t("Scheduled {start} – {end} · {site}", { start: sched.start, end: sched.end, site: t(sched.key) })}</div>
            <div style={{ fontSize: 11.5, color: tokens.faint }}>
              {t("Tolerated until {grace} · Break {bs}–{be}", { grace: sched.graceUntil, bs: dowOf(TODAY_STR) === 5 ? sched.fridayBreakStart : sched.breakStart, be: dowOf(TODAY_STR) === 5 ? sched.fridayBreakEnd : sched.breakEnd })}
            </div>
          </div>
        </div>

        <div className="hris-today-stats" style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", padding: "6px 18px 14px" }}>
          {[
            { label: t("Clock in"), value: today.clockIn || "—",
              sub: today.clockIn ? (today.lateMin > 0 ? t("{d} past {grace}", { d: fmtDelta(today.lateMin), grace: sched.graceUntil }) : t(METHOD_LABEL[today.method] || "On time")) : t("Not recorded yet"),
              tone: today.lateMin > 0 ? tokens.warning : tokens.muted },
            { label: t("Clock out"), value: today.clockOut || "—",
              sub: today.clockOut ? (today.otMin > 0 ? `${t("Overtime")} +${fmtDelta(today.otMin)}` : today.earlyLeaveMin > 0 ? `${t("Early leave")} −${fmtDelta(today.earlyLeaveMin)}` : t("On schedule")) : t("Still open"),
              tone: today.earlyLeaveMin > 0 ? tokens.warning : tokens.muted },
            { label: t("Status"), node: <StatusPill status={today.status} />,
              sub: today.clockOut ? t("Worked {d}", { d: formatDuration(today.workedMin) }) : today.clockIn ? t("Working {d} so far", { d: formatDuration(workedSoFar) }) : "—",
              tone: tokens.muted },
          ].map((c, i) => (
            <div key={c.label} className="hris-today-cell" style={{ paddingLeft: i ? 18 : 0 }}>
              <div style={{ fontSize: 12, color: tokens.muted, marginBottom: 4 }}>{c.label}</div>
              {c.node || <div style={{ fontSize: 20, fontWeight: 600, color: tokens.ink, fontVariantNumeric: "tabular-nums", letterSpacing: -0.4 }}>{c.value}</div>}
              <div style={{ fontSize: 11.5, color: c.tone, marginTop: 3 }}>{c.sub}</div>
            </div>
          ))}
        </div>

        {today.risk.level !== RISK.VALID && (
          <div style={{ margin: "0 18px 14px", padding: "9px 12px", borderRadius: 8, background: tokens.infoSoft, fontSize: 12.5, color: tokens.info }}>
            {t("This record is flagged for review — a supervisor will confirm it. Nothing has been decided.")}
          </div>
        )}

        <div style={{ borderTop: `1px solid ${tokens.border}`, padding: "14px 18px" }}>
          {[ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY].includes(today.status) ? (
            <div style={{ fontSize: 13, color: tokens.muted }}>No schedule today — {today.holidayName || "rest day"}.</div>
          ) : today.status === ATT_STATUS.ON_LEAVE ? (
            <div style={{ fontSize: 13, color: tokens.muted }}>{t("You are on approved leave today. No attendance is expected.")}</div>
          ) : confirm ? (
            <div style={{ background: tokens.bg, border: `1px solid ${tokens.border}`, borderRadius: 10, padding: 14 }}>
              <div style={{ fontSize: 13.5, fontWeight: 600, color: tokens.ink, marginBottom: 4 }}>{confirmCopy[confirm].title}</div>
              <p style={{ fontSize: 12.5, color: tokens.inkSoft, margin: "0 0 12px", lineHeight: 1.5 }}>{confirmCopy[confirm].body}</p>
              <div style={{ display: "flex", gap: 8 }}>
                <Button
                  size="sm"
                  onClick={() => {
                    appendEvent(makeDeviceEvent(
                      viewer,
                      confirm === "out" ? "CHECK_OUT" : "CHECK_IN",
                      sched,
                      confirm === "in-mobile" ? METHOD.MOBILE_GPS : METHOD.FINGERPRINT
                    ));
                    setConfirm(null);
                  }}
                >{t("Append event")}</Button>
                <Button size="sm" variant="ghost" onClick={() => setConfirm(null)}>{t("Cancel")}</Button>
              </div>
            </div>
          ) : canCheckIn ? (
            <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <Button variant="secondary" size="sm" icon={Fingerprint} onClick={() => setConfirm("in")}>{t("Simulate fingerprint check-in (demo)")}</Button>
              <Button variant="ghost" size="sm" icon={Smartphone} onClick={() => setConfirm("in-mobile")}>{t("Simulate mobile check-in")}</Button>
            </div>
          ) : canCheckOut ? (
            <Button variant="secondary" size="sm" icon={Fingerprint} onClick={() => setConfirm("out")}>{t("Simulate fingerprint check-out (demo)")}</Button>
          ) : (
            <div style={{ fontSize: 13, color: tokens.muted }}>{t("Today's record has been received from the device — nothing left to simulate.")}</div>
          )}
          <p style={{ fontSize: 11.5, color: tokens.faint, margin: "10px 0 0", lineHeight: 1.5 }}>
            {t("Attendance is captured by the fingerprint reader, the mobile app, or a Hadir import — never by this browser. These buttons append a simulated device event so the flow can be demonstrated.")}
          </p>
        </div>
      </Card>

      <Card
        title={monthOptions.find((m) => m.key === month)?.label || month}
        action={
          <Select value={month} onChange={(e) => setMonth(e.target.value)} style={{ width: 160 }}>
            {monthOptions.map((m) => <option key={m.key} value={m.key}>{m.label}</option>)}
          </Select>
        }
      >
        <div style={{ display: "flex", padding: "2px 18px 16px", gap: 26, flexWrap: "wrap" }}>
          {[
            [t("Present"), summary.present], [t("Late"), summary.late], [t("Absent"), summary.absent],
            [t("Early leave"), summary.earlyLeave], [t("Field work"), summary.fieldWork],
            [t("Overtime"), formatDuration(summary.overtimeMin)],
          ].map(([l, v]) => (
            <div key={l}>
              <div style={{ fontSize: 18, fontWeight: 600, color: tokens.ink, fontVariantNumeric: "tabular-nums" }}>{v}</div>
              <div style={{ fontSize: 12, color: tokens.muted }}>{l}</div>
            </div>
          ))}
        </div>
      </Card>

      <div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10, gap: 12, flexWrap: "wrap" }}>
          <span style={{ fontSize: 13.5, fontWeight: 600, color: tokens.ink }}>{t("History")}</span>
          <Select value={sort} onChange={(e) => setSort(e.target.value)} style={{ width: 190 }}>
            <option value="date">{t("Sort: Newest first")}</option>
            <option value="exception">{t("Sort: Exceptions first")}</option>
          </Select>
        </div>
        <div style={{ background: tokens.surface, border: `1px solid ${tokens.border}`, borderRadius: 10, overflow: "hidden" }}>
          <AttendanceTable
            rows={workRecords.slice().sort(ATT_SORTERS[sort])}
            columns={["date", "in", "out", "hours", "method", "location", "late", "early", "ot", "status", "correction"]}
            minWidth={940}
            onRowClick={onOpenRecord}
            emptyState={<EmptyState icon={Clock} title={t("No attendance records")} subtitle={t("Nothing recorded for {month}.", { month: (monthOptions.find((m) => m.key === month) || {}).label || month })} />}
          />
        </div>
        <p style={{ fontSize: 11.5, color: tokens.faint, margin: "10px 0 0" }}>
          {t("You can't edit attendance directly. Open a day and request a correction — HR reviews every change.")}
        </p>
      </div>
    </div>
  );
}

