function TeamAttendance({ session, viewer, roster, getRecord, corrections, onOpenRecord, onOpenCorrectionId }) {
  const [span, setSpan] = useState("today");
  const [sort, setSort] = useState("exception");
  const [empFilter, setEmpFilter] = useState("");
  const [openCorr, setOpenCorr] = useState(null);
  const canApprove = canApproveCorrections(session.role);

  const range = useMemo(() => {
    if (span === "today") return { days: [TODAY_STR] };
    if (span === "week") return { days: weeklyPeriod(TODAY_STR).days.filter((d) => d <= TODAY_STR) };
    return { days: weeklyPeriod(addDays(TODAY_STR, -7)).days };
  }, [span]);

  const rows = useMemo(() => {
    const out = [];
    for (const e of roster) {
      if (empFilter && e.id !== empFilter) continue;
      for (const d of range.days) {
        const rec = getRecord(e.id, d);
        if ([ATT_STATUS.WEEKEND, ATT_STATUS.HOLIDAY].includes(rec.status)) continue;
        out.push(decorateRecord(rec));
      }
    }
    return out.sort(ATT_SORTERS[sort]);
  }, [roster, range, getRecord, sort, empFilter]);

  const board = useMemo(() => todayBoard(roster, TODAY_STR), [roster]);
  const teamCorrections = corrections.filter(
    (c) => c.state === "Pending" && roster.some((e) => e.id === c.employeeId)
  );

  if (!roster.length) {
    return <EmptyState icon={Users} title={t("No one in scope")} subtitle={t("You don't have anyone reporting to you yet.")} />;
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
        <div style={{ fontSize: 13, color: tokens.muted }}>
          {session.role === "HR" ? t("All employees") : session.role === "Manager" ? t("{dept} department", { dept: viewer.dept }) : t("Direct reports")} · {t("{n} people", { n: roster.length })}
        </div>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <Select value={empFilter} onChange={(e) => setEmpFilter(e.target.value)} style={{ width: 180 }}>
            <option value="">{t("Everyone in scope")}</option>
            {roster.map((e) => <option key={e.id} value={e.id}>{e.name}</option>)}
          </Select>
          <Select value={span} onChange={(e) => setSpan(e.target.value)} style={{ width: 150 }}>
            <option value="today">{t("Today")}</option>
            <option value="week">{t("This Week")}</option>
            <option value="lastweek">{t("Last week")}</option>
          </Select>
          <Select value={sort} onChange={(e) => setSort(e.target.value)} style={{ width: 190 }}>
            <option value="exception">{t("Sort: Exceptions first")}</option>
            <option value="name">{t("Sort: Name")}</option>
          </Select>
        </div>
      </div>

      {span === "today" && (
        <div style={{ display: "flex", background: tokens.surface, border: `1px solid ${tokens.border}`, borderRadius: 10, overflow: "hidden" }}>
          {[
            [t("Present"), board.counts.present], [t("Late"), board.counts.late], [t("Absent"), board.counts.absent],
            [t("Field work"), board.counts.fieldWork], [t("No check-in"), board.counts.notClockedIn],
            [t("Needs review"), board.counts.needsReview],
          ].map(([l, v], i) => (
            <div key={l} style={{ flex: 1, padding: "13px 16px", borderLeft: i ? `1px solid ${tokens.border}` : "none" }}>
              <div style={{ fontSize: 20, fontWeight: 600, color: v === 0 ? tokens.faint : tokens.ink, fontVariantNumeric: "tabular-nums", letterSpacing: -0.4 }}>{v}</div>
              <div style={{ fontSize: 11.5, color: tokens.muted, marginTop: 2 }}>{l}</div>
            </div>
          ))}
        </div>
      )}

      <div style={{ background: tokens.surface, border: `1px solid ${tokens.border}`, borderRadius: 10, overflow: "hidden" }}>
        <AttendanceTable
          rows={rows}
          columns={["employee", "date", "in", "out", "hours", "method", "location", "late", "ot", "status", "risk", "actions"]}
          minWidth={1120}
          onRowClick={onOpenRecord}
          emptyState={<EmptyState icon={Clock} title={t("Nothing recorded")} subtitle={t("No attendance in this period for your team.")} />}
        />
      </div>

      <Card title={t("Correction requests from your team")}>
        {teamCorrections.length === 0 ? (
          <div style={{ padding: "0 16px 16px", fontSize: 13, color: tokens.muted }}>
            {t("No pending correction requests from your team.")}
          </div>
        ) : (
          <div style={{ padding: "0 8px 10px" }}>
            {teamCorrections.map((c) => (
              <div key={c.id} style={{ borderTop: `1px solid ${tokens.border}` }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 8px" }}>
                  <Avatar name={employeeById(c.employeeId).name} color={colorFor(employeeById(c.employeeId).colorSeed || 0)} soft={colorSoftFor(employeeById(c.employeeId).colorSeed || 0)} size={26} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 13, color: tokens.ink }}>
                      {employeeById(c.employeeId).name} <span style={{ color: tokens.muted }}>· {t(CORRECTION_ISSUE[c.issueType].label)} · {fmtDateShort(c.date)}</span>
                    </div>
                    <div style={{ fontSize: 12, color: tokens.muted, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{c.reason}</div>
                  </div>
                  {canApprove
                    ? <Button size="sm" variant="ghost" onClick={() => onOpenCorrectionId(c.id)}>{t("Open")}</Button>
                    : <Button size="sm" variant="ghost" onClick={() => setOpenCorr(openCorr === c.id ? null : c.id)}>{openCorr === c.id ? t("Hide") : t("View")}</Button>}
                </div>
                {!canApprove && openCorr === c.id && (
                  <div style={{ padding: "0 8px 12px" }}>
                    <CorrectionCompare correction={c} resultStatus={c.appliedPatch ? c.appliedPatch.status : null} />
                    {c.evidence && c.evidence.length > 0 && (
                      <div style={{ fontSize: 12, color: tokens.muted, marginTop: 8 }}>
                        {t("Evidence: {files}", { files: c.evidence.map((f) => f.name).join(", ") })}
                      </div>
                    )}
                    <div style={{ fontSize: 11.5, color: tokens.faint, marginTop: 8 }}>{t("Read-only — HR decides this request.")}</div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </Card>
      <p style={{ fontSize: 11.5, color: tokens.faint, margin: 0 }}>
        {t("Corrections are decided by HR. You can see and comment on your team\u2019s requests, not approve them.")}
      </p>
    </div>
  );
}

