              {[t("Employee"), t("Device"), t("OS"), t("App"), t("Registered"), t("Last seen"), t("Integrity")].map((h) => (
                <th key={h} style={{ textAlign: "left", fontSize: 11.5, fontWeight: 600, color: tokens.faint, textTransform: "uppercase", padding: "8px 16px" }}>{h}</th>
              ))}
